// ======================================================================================
// TARJETA EJECUTIVA — KPIs ÚLTIMO 1 MIN (VENTANA CERRADA)
// Disponibilidad solo en ecosistema completo
// Si hay filtro y total_tx = 0: muestra mensaje de no transaccionamiento
// ======================================================================================

const aqua = "#00F4C4";
const aquaSoft = "rgba(0,244,196,0.10)";
const amber = "#E7B432";
const amberSoft = "rgba(231,180,50,0.10)";
const blue = "#3B82F6";
const green = "#22C55E";
const violet = "#7C6AE6";
const coral = "#CF4360";
const coralSoft = "rgba(207,67,96,0.12)";

const bg = "#0a0e17";
const cardSoft = "#111827";
const border = "rgba(148,163,184,0.18)";
const textSec = "#8b93a7";
const textSoft = "#CBD5E1";
const textWhite = "#FFFFFF";
const neutralSoft = "rgba(148,163,184,0.07)";

const series = context.panel?.data?.series || [];
const s = series[0];

function col(name) {
  if (!s) return null;
  const f = s.fields.find(x => x.name === name);
  const v = f?.values?.toArray ? f.values.toArray() : (f?.values || []);
  return v.length ? v[0] : null;
}

const num = (v, d = 0) => {
  const x = Number(v);
  return Number.isFinite(x) ? x : d;
};

const fmt = (v, d = 1) => {
  const x = Number(v);
  return Number.isFinite(x) ? x.toFixed(d) : "—";
};

const fmtNum = v => num(v).toLocaleString("es-AR");

const fmtFecha = v => {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return "—";
  return d.toLocaleString("es-AR", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  });
};

function labelMarca(v) {
  const x = String(v ?? "-1").toUpperCase();

  if (x === "-1" || x === "ALL" || x === "TODAS LAS MARCAS") {
    return "Todas las marcas";
  }

  const map = {
    VISA: "Visa",
    MASTERCARD: "Mastercard",
    AMEX: "Amex",
    CABAL_DISCOVER: "Cabal / Discover",
    UPI: "UPI",
    OTRAS: "Otras"
  };

  return map[x] || x;
}

function labelEstablecimiento(v) {
  const x = String(v ?? "-1");

  if (x === "-1" || x === "" || x.toUpperCase() === "ALL") {
    return "Todos los est.";
  }

  return `Est. ${x}`;
}

const CLIENTES = {
  "30641405554": { nombre: "AEROLINEAS ARGENTINAS", color: green },
  "30503612891": { nombre: "BGH", color: green },
  "30663205621": { nombre: "CAJA DE SEGUROS", color: green },
  "30590360763": { nombre: "CENCOSUD", color: aqua },
  "30592845748": { nombre: "CETROGAR", color: amber },
  "30663288497": { nombre: "CLARO", color: blue },
  "30680743068": { nombre: "CLARO PAY", color: blue },
  "30525705931": { nombre: "COOPERATIVA OBRERA", color: aqua },
  "30548083156": { nombre: "COTO CICSA", color: aqua },
  "30638485733": { nombre: "DABRA SA", color: amber },
  "30718955722": { nombre: "DECATHLON", color: amber },
  "30516186670": { nombre: "DEHEZA SA", color: aqua },
  "30701307115": { nombre: "DESPEGAR", color: amber },
  "30711998612": { nombre: "DLP", color: amber },
  "30655116202": { nombre: "EDENOR", color: green },
  "30692138747": { nombre: "FARMACITY", color: aqua },
  "33707366589": { nombre: "FED. PATRONAL", color: green },
  "30526874249": { nombre: "FRAVEGA", color: amber },
  "30715621866": { nombre: "GMRA SA", color: amber },
  "30687310434": { nombre: "INC SA", color: amber },
  "30506730038": { nombre: "LA ANONIMA", color: aqua },
  "30703088534": { nombre: "MERCADO LIBRE", color: amber },
  "30532847547": { nombre: "MEGATONE", color: amber },
  "33707013139": { nombre: "MOSTAZA Y PAN", color: green },
  "30543659734": { nombre: "ON CITY", color: amber },
  "30711792186": { nombre: "PAGO VIRTUAL DEL SUR", color: violet },
  "30714407313": { nombre: "PAGOS360", color: violet },
  "30715221159": { nombre: "PAGOSYA", color: violet },
  "30695542476": { nombre: "PAN AMERICAN ENERGY", color: amber },
  "30708743514": { nombre: "PAYU", color: violet },
  "30707743987": { nombre: "PLUS PAGOS", color: violet },
  "30704950345": { nombre: "PROVINCIA NET", color: violet },
  "30659863789": { nombre: "SERV. ELECTRONICO DE PAGO", color: violet },
  "30612865333": { nombre: "VITAL", color: aqua },
  "30589621499": { nombre: "MAKRO", color: aqua },
  "30654855168": { nombre: "SWISS MEDICAL", color: green },
  "30640897267": { nombre: "TELECENTRO", color: blue },
  "30639453738": { nombre: "TELECOM", color: blue },
  "30678814357": { nombre: "MOVISTAR", color: blue },
  "33690765549": { nombre: "TICKETEK", color: green },
  "30715778722": { nombre: "TODOTRAIL", color: amber },
  "30716370964": { nombre: "VIUMI", color: amber },
  "30655534462": { nombre: "VISUAR", color: violet }
};

const TOTAL_CLIENTES = Object.keys(CLIENTES).length; // 43

const GLOBAL_CLIENTE = { nombre: "PAYWAY GENERAL", color: textSec };

const rawCuit = col("cuit");
const disponibilidad = col("disponibilidad_pct");
const tasa = col("tasa_aceptacion");
const reversos = col("reversos");
const latencia = col("latencia_ms");
const total = col("total_tx");

const establecimientoFiltro = col("establecimiento_filtro");
const marcaFiltro = col("marca_filtro");

let cliente = GLOBAL_CLIENTE;

if (rawCuit && String(rawCuit) !== "-1" && String(rawCuit) !== "1") {
  const norm = String(rawCuit).replace(/[^0-9]/g, "");
  cliente = CLIENTES[norm] || { nombre: `CUIT ${norm}`, color: textSec };
}

const establecimientoTxt = labelEstablecimiento(establecimientoFiltro);
const marcaTxt = labelMarca(marcaFiltro);

const rangoTxt = fmtFecha(col("rango_desde")) + " – " + fmtFecha(col("rango_hasta"));

// La query debe devolver disponibilidad_pct NULL cuando hay filtro.
// Si disponibilidad_pct viene con número, es ecosistema global.
const mostrarDisponibilidad =
  disponibilidad !== null &&
  disponibilidad !== undefined &&
  Number.isFinite(Number(disponibilidad));

const sinTransaccionamientoFiltrado =
  !mostrarDisponibilidad && num(total, 0) === 0;

const W = context?.width || 650;
const H = context?.height || 280;

const compact = W < 420 || H < 240;
const base = Math.max(11, Math.min(16, W * 0.0195));

const headerH = compact ? 30 : 34;
const kpiW = 41;
const kpiH = compact ? 20.5 : 22.5;

const leftX = 7;
const rightX = 52;
const row1Y = compact ? 27 : 28;
const row2Y = compact ? 53 : 56;

const labelFont = `${base * 0.70}px sans-serif`;
const valueFont = `bold ${base * 1.05}px sans-serif`;

function kpiStatusColor(value, type) {
  const x = num(value, 0);

  if (type === "tasa") return aqua;
  if (type === "disp") return x === 100 ? aqua : coral;
  if (type === "reversos") return x > 0 ? coral : textSoft;

  if (type === "latencia") {
    if (x <= 0) return textSoft;
    if (x <= 3000) return amber;
    return coral;
  }

  return textWhite;
}

function kpiBg(value, type) {
  if (type === "tasa") return neutralSoft;

  const c = kpiStatusColor(value, type);

  if (c === aqua) return aquaSoft;
  if (c === amber) return amberSoft;
  if (c === coral) return coralSoft;

  return neutralSoft;
}

const g = [];

function addKpi({ x, y, label, value, suffix = "", color, bgFill, icon }) {
  g.push({
    type: "rect",
    left: `${x}%`,
    top: `${y}%`,
    shape: {
      width: `${kpiW}%`,
      height: `${kpiH}%`,
      r: 8
    },
    style: {
      fill: bgFill || cardSoft,
      stroke: border,
      lineWidth: 1
    },
    silent: true
  });

  g.push({
    type: "text",
    left: `${x + 3}%`,
    top: `${y + 2.8}%`,
    style: {
      text: `${icon} ${label}`,
      fill: textSec,
      font: labelFont
    },
    silent: true
  });

  g.push({
    type: "text",
    left: `${x + 3}%`,
    top: `${y + 10.0}%`,
    style: {
      text: `${value}${suffix}`,
      fill: color,
      font: valueFont
    },
    silent: true
  });
}

g.push({
  type: "rect",
  left: "2%",
  top: "3%",
  shape: {
    width: "96%",
    height: "94%",
    r: 12
  },
  style: {
    fill: bg,
    stroke: "rgba(148,163,184,0.08)",
    lineWidth: 1
  },
  silent: true
});

g.push({
  type: "rect",
  left: "20%",
  top: "5.5%",
  shape: {
    width: "60%",
    height: headerH,
    r: 10
  },
  style: {
    fill: aquaSoft,
    stroke: "rgba(0,244,196,0.42)",
    lineWidth: 1.2,
    shadowBlur: 10,
    shadowColor: "rgba(0,244,196,0.16)"
  },
  silent: true
});

g.push({
  type: "text",
  left: "50%",
  top: compact ? "6.8%" : "6.6%",
  style: {
    text: rangoTxt,
    fill: aqua,
    font: `bold ${base * 0.92}px sans-serif`,
    textAlign: "center"
  },
  silent: true
});

g.push({
  type: "text",
  left: "50%",
  top: compact ? "12.3%" : "11.8%",
  style: {
    text: "minuto cerrado",
    fill: textSec,
    font: `${base * 0.62}px sans-serif`,
    textAlign: "center"
  },
  silent: true
});

if (sinTransaccionamientoFiltrado) {
  g.push({
    type: "rect",
    left: "7%",
    top: "27%",
    shape: {
      width: "86%",
      height: "42%",
      r: 12
    },
    style: {
      fill: neutralSoft,
      stroke: border,
      lineWidth: 1
    },
    silent: true
  });

  g.push({
    type: "text",
    left: "50%",
    top: "38%",
    style: {
      text: "No hubo transaccionamiento",
      fill: textWhite,
      font: `bold ${base * 0.92}px sans-serif`,
      textAlign: "center",
      width: W * 0.78,
      overflow: "truncate"
    },
    silent: true
  });

  g.push({
    type: "text",
    left: "50%",
    top: "49%",
    style: {
      text: "en el último minuto",
      fill: textSec,
      font: `${base * 0.72}px sans-serif`,
      textAlign: "center"
    },
    silent: true
  });
} else {
  addKpi({
    x: leftX,
    y: row1Y,
    label: "Aceptación",
    value: fmt(tasa, 1),
    suffix: "%",
    icon: "●",
    color: kpiStatusColor(tasa, "tasa"),
    bgFill: kpiBg(tasa, "tasa")
  });

  if (mostrarDisponibilidad) {
    addKpi({
      x: rightX,
      y: row1Y,
      label: "Disponibilidad",
      value: fmt(disponibilidad, 0),
      suffix: "%",
      icon: "●",
      color: kpiStatusColor(disponibilidad, "disp"),
      bgFill: kpiBg(disponibilidad, "disp")
    });

    addKpi({
      x: rightX,
      y: row2Y,
      label: "Latencia p95",
      value: fmt(latencia, 0),
      suffix: " ms",
      icon: "●",
      color: kpiStatusColor(latencia, "latencia"),
      bgFill: kpiBg(latencia, "latencia")
    });
  } else {
    addKpi({
      x: rightX,
      y: row1Y,
      label: "Latencia p95",
      value: fmt(latencia, 0),
      suffix: " ms",
      icon: "●",
      color: kpiStatusColor(latencia, "latencia"),
      bgFill: kpiBg(latencia, "latencia")
    });
  }

  addKpi({
    x: leftX,
    y: row2Y,
    label: "Reversos",
    value: fmtNum(reversos),
    icon: "●",
    color: kpiStatusColor(reversos, "reversos"),
    bgFill: kpiBg(reversos, "reversos")
  });
}

g.push({
  type: "line",
  left: "6%",
  top: "81.5%",
  shape: {
    x1: 0,
    y1: 0,
    x2: W * 0.88,
    y2: 0
  },
  style: {
    stroke: "rgba(148,163,184,0.14)",
    lineWidth: 1
  },
  silent: true
});

g.push({
  type: "text",
  left: "7%",
  bottom: 14,
  style: {
    text: `${fmtNum(total)} tx`,
    fill: textSoft,
    font: `bold ${base * 0.72}px sans-serif`
  },
  silent: true
});

g.push({
  type: "text",
  right: 12,
  bottom: 21,
  style: {
    text: cliente.nombre,
    fill: cliente.color,
    font: `bold ${base * 0.72}px sans-serif`,
    textAlign: "right"
  },
  silent: true
});

g.push({
  type: "text",
  right: 12,
  bottom: 8,
  style: {
    text: `${establecimientoTxt} · ${marcaTxt}`,
    fill: textSec,
    font: `${base * 0.62}px sans-serif`,
    textAlign: "right"
  },
  silent: true
});

const tooltipBase = {
  trigger: "item",
  confine: true,
  backgroundColor: "#0b0f18",
  borderColor: aqua,
  borderWidth: 1,
  padding: [7, 9],
  textStyle: {
    color: "#ffffff",
    fontSize: 11,
    lineHeight: 15,
    width: 220,
    overflow: "break"
  },
  extraCssText: `
    max-width: 230px;
    white-space: normal;
    word-break: break-word;
  `
};

const tooltipSeries = [];

if (!sinTransaccionamientoFiltrado) {
  tooltipSeries.push(
    {
      type: "scatter",
      data: [[24, 70]],
      symbolSize: [160, 80],
      itemStyle: { opacity: 0 },
      tooltip: {
        ...tooltipBase,
        formatter:
          "<b>Aceptación</b><br/>" +
          "Aprobadas sobre total operativo del último minuto cerrado."
      }
    },
    {
      type: "scatter",
      data: [[24, 42]],
      symbolSize: [160, 80],
      itemStyle: { opacity: 0 },
      tooltip: {
        ...tooltipBase,
        formatter:
          "<b>Reversos</b><br/>" +
          "Cantidad de reversos registrados en la ventana."
      }
    },
    {
      type: "scatter",
      data: mostrarDisponibilidad ? [[76, 42]] : [[76, 70]],
      symbolSize: [160, 80],
      itemStyle: { opacity: 0 },
      tooltip: {
        ...tooltipBase,
        formatter:
          "<b>Latencia p95</b><br/>" +
          "Tiempo de respuesta p95 registrado en la ventana."
      }
    }
  );

  if (mostrarDisponibilidad) {
    tooltipSeries.push({
      type: "scatter",
      data: [[76, 70]],
      symbolSize: [160, 80],
      itemStyle: { opacity: 0 },
      tooltip: {
        ...tooltipBase,
        formatter:
          "<b>Disponibilidad</b><br/>" +
          "Estado operativo global del último minuto cerrado."
      }
    });
  }
}

return {
  backgroundColor: bg,
  graphic: g,
  animation: false,
  tooltip: tooltipBase,

  xAxis: { show: false, min: 0, max: 100 },
  yAxis: { show: false, min: 0, max: 100 },

  series: tooltipSeries
};

