  "33707013139": { nombre: "MOSTAZA Y PAN", color: green },
  "30543659734": { nombre: "ON CITY", color: amber },
  "30711792186": { nombre: "PAGO VIRTUAL DEL SUR", color: violet },
  "30714407313": { nombre: "PAGOS360", color: violet },
  "30715221159": { nombre: "PAGOSYA", color: violet },
  "30695542476": { nombre: "PAN AMERICAN ENERGY", color: amber },
  "30708743514": { nombre: "PAYU", color: violet },
  "30707743987": { nombre: "PLUS PAGOS", color: violet },
  "30704950345": { nombre: "PROVINCIA NET", color: violet },
  "30659863789": { nombre: "SERV. ELECTRONICO DE PAGO", color: violet },
  "30612865333": { nombre: "VITAL", color: aqua },
  "30589621499": { nombre: "MAKRO", color: aqua },
  "30654855168": { nombre: "SWISS MEDICAL", color: green },
  "30640897267": { nombre: "TELECENTRO", color: blue },
  "30639453738": { nombre: "TELECOM", color: blue },
  "30678814357": { nombre: "MOVISTAR", color: blue },
  "33690765549": { nombre: "TICKETEK", color: green },
  "30715778722": { nombre: "TODOTRAIL", color: amber },
  "30716370964": { nombre: "VIUMI", color: amber },
  "30655534462": { nombre: "VISUAR", color: violet }
};

const GLOBAL_CLIENTE = { nombre: "PAYWAY GENERAL", color: textSec };

// ---------- DATA ----------
const series = context.panel?.data?.series || [];
const s = series[0];

function valuesOfField(f) {
  if (!f) return [];
  if (typeof f.values?.toArray === "function") return f.values.toArray();
  return Array.from(f.values || []);
}

function fieldAny(names) {
  if (!s || !s.fields) return [];
  for (const name of names) {
    const f = s.fields.find(x =>
      String(x.name).toLowerCase() === String(name).toLowerCase()
    );
    const vals = valuesOfField(f);
    if (vals.length) return vals;
  }
  return [];
}

function num(v, d = 0) {
  const x = Number(v);
  return Number.isFinite(x) ? x : d;
}

function fmtNum(v) {
  return num(v).toLocaleString("es-AR");
}

function fmtPct(v) {
  return `${num(v).toFixed(1)}%`;
}

function esc(v) {
  return String(v ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function shortText(v, max = 23) {
  const t = String(v ?? "Sin descripcion");
  return t.length > max ? `${t.slice(0, max - 1)}...` : t;
}

function fmtFechaHoraCorta(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);

  const fecha = d.toLocaleDateString("es-AR", {
    day: "2-digit",
    month: "2-digit"
  });

  const hora = d.toLocaleTimeString("es-AR", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  });

  return `${fecha} ${hora}`;
}

function colorCuadrante(q) {
  return COLORS[String(q || "Otros")] || COLORS["Otros"];
}

function normalizeCuadrante(v) {
  const raw = String(v ?? "Otros").trim();
  const upper = raw.toUpperCase();

  if (COLORS[raw]) return raw;

  if (upper === "RIESGO EMISOR") return "Riesgo Emisor";
  if (upper === "OPERATIVO EMISOR") return "Operativo Emisor";
  if (upper === "RIESGO ADQUIRENTE") return "Riesgo Adquirente";
  if (upper === "OPERATIVO ADQUIRENTE") return "Operativo Adquirente";

  if (upper === "EMISOR NO CATALOGADO") return "Emisor no catalogado";
  if (upper === "CODIGO EMISOR DE OTRAS MARCAS") return "Emisor no catalogado";
  if (upper === "CODIGO EMISOR - MARCA NO MAPEADA") return "Emisor no catalogado";
  if (upper === "ISSUER NO MAPEADO") return "Emisor no catalogado";
  if (upper === "EMISOR NO MAPEADO") return "Emisor no catalogado";

  if (upper === "SIN CODIGO INFORMADO") return "Sin codigo informado";
  if (upper === "OTROS") return "Otros";
  if (upper === "NO CLASIFICADO") return "Otros";

  return raw;
}

function labelMarca(v) {
  const x = String(v ?? "-").toUpperCase();

  const map = {
    VISA: "Visa",
    MASTERCARD: "Mastercard",
    AMEX: "Amex",
    CABAL_DISCOVER: "Cabal / Discover",
    CABAL: "Cabal / Discover",
    DISCOVER: "Cabal / Discover",
    UPI: "UPI",
    OTRAS: "Otras",
    OTRA: "Otras",
    "-": "-"
  };

  return map[x] || x;
}

function prettyCodigo(v) {
  const x = String(v ?? "-").trim();

  if (!x || x === "-") return "-";
  if (x === "SIN_DESC") return "Sin catalogo";
  if (x === "SIN_CODIGO") return "S/C";

  return x;
}

function rv(str) {
  try {
    if (context?.grafana?.replaceVariables) {
      return context.grafana.replaceVariables(str);
    }
  } catch (e) { }
  return str;
}

function cleanValue(v) {
  const x = String(v ?? "").trim();

  if (!x) return null;
  if (x === "-1") return null;
  if (x.toUpperCase() === "ALL") return null;
  if (x.toUpperCase() === "TODAS LAS MARCAS") return null;

  return x;
}

function noHayRechazos() {
  return {
    backgroundColor: bg,
    graphic: [
      {
        type: "text",
        left: 10,
        top: 8,
        style: {
          text: "Top causas 60m",
          fill: aqua,
          font: "800 12px sans-serif"
        },
        silent: true
      },
      {
        type: "text",
        left: "center",
        top: "middle",
        style: {
          text: "No hay rechazos",
          fill: textSec,
          font: "800 12px sans-serif",
          textAlign: "center"
        },
        silent: true
      }
    ],
    xAxis: { show: false },
    yAxis: { show: false },
    series: [],
    animation: false
  };
}

// ---------- VARIABLES ----------
const selectedClienteRaw =
  cleanValue(rv("${cuit:raw}")) ||
  cleanValue(rv("${cuit:label}"));

let cliente = GLOBAL_CLIENTE;

if (selectedClienteRaw) {
  const c = String(selectedClienteRaw).replace(/[^0-9]/g, "");
  cliente = CLIENTES[c] || { nombre: `CUIT ${c}`, color: textSec };
}

const selectedEst = cleanValue(rv("${establecimiento:raw}"));
const selectedMarcaRaw = cleanValue(rv("${marca:raw}"));
const selectedMarca = selectedMarcaRaw ? labelMarca(selectedMarcaRaw) : null;

// ---------- EMPTY ----------
if (!s || !s.fields || s.fields.length === 0) {
  return noHayRechazos();
}

// ---------- CAMPOS ----------
const ranks = fieldAny(["rank_causa", "rank", "ranking"]);
const cuadrantes = fieldAny(["cuadrante", "quadrant", "cuadrante_mapeado"]);
const codigos = fieldAny(["codigo", "codigo_detalle", "codigo_join", "codresp"]);
const descripciones = fieldAny(["descripcion", "descripcion_codigo", "causa"]);
const marcas = fieldAny(["marca", "marca_tx"]);
const origenes = fieldAny(["origen_codigo", "origen"]);
const tipos = fieldAny(["tipo_codigo", "tipo"]);
const rechazosVals = fieldAny(["rechazos", "denegadas", "total_denegadas", "count", "cantidad", "total_rechazos", "rechazos_codigo"]);
const totalDenegadasVals = fieldAny(["total_denegadas"]);
const pctDenegadasVals = fieldAny(["pct_denegadas"]);
const desdeVals = fieldAny(["rango_desde", "desde"]);
const hastaVals = fieldAny(["rango_hasta", "hasta"]);

if (!rechazosVals.length) {
  return noHayRechazos();
}

// ---------- NORMALIZACION ----------
let rows = [];

for (let i = 0; i < rechazosVals.length; i++) {
  const rech = num(rechazosVals[i], 0);
  if (rech <= 0) continue;

  const cuadrante = normalizeCuadrante(cuadrantes[i]);

  rows.push({
    rank: num(ranks[i], i + 1),
    cuadrante,
    codigo: prettyCodigo(codigos[i]),
    descripcion: String(descripciones[i] ?? "Sin descripcion"),
    marca: String(marcas[i] ?? "-"),
    origen: String(origenes[i] ?? "-"),
    tipo: String(tipos[i] ?? "-"),
    rechazos: rech,
    pct: null,
    color: colorCuadrante(cuadrante)
  });
}

// ---------- AGRUPACION POR CAUSA ----------
const groupedMap = new Map();

rows.forEach(r => {
  const key = `${r.cuadrante}__${r.descripcion}`;

  if (!groupedMap.has(key)) {
    groupedMap.set(key, {
      rank: r.rank,
      cuadrante: r.cuadrante,
      codigo: r.codigo,
      descripcion: r.descripcion,
      marca: "VARIAS",
      origen: r.origen,
      tipo: r.tipo,
      rechazos: 0,
      pct: null,
      color: r.color,
      detalles: []
    });
  }

  const item = groupedMap.get(key);
  item.rechazos += r.rechazos;
  item.detalles.push(r);

  item.codigo = [...new Set(item.detalles.map(d => d.codigo))].join(" / ");
  item.marca = [...new Set(item.detalles.map(d => labelMarca(d.marca)))].join(", ");
});

rows = Array.from(groupedMap.values());

rows.sort((a, b) => {
  if (b.rechazos !== a.rechazos) return b.rechazos - a.rechazos;

  const oa = ORDER[a.cuadrante] || 99;
  const ob = ORDER[b.cuadrante] || 99;
  if (oa !== ob) return oa - ob;

  return String(a.descripcion).localeCompare(String(b.descripcion));
});

rows = rows.map((r, i) => ({
  ...r,
  rank: i + 1
}));

const totalQuery = totalDenegadasVals.length ? num(totalDenegadasVals[0], 0) : 0;
const total = totalQuery > 0
  ? totalQuery
  : rows.reduce((acc, r) => acc + r.rechazos, 0);

rows.forEach(r => {
  r.pct = total > 0 ? (r.rechazos * 100) / total : 0;
});

if (!rows.length || total === 0) {
  return noHayRechazos();
}

// ---------- RESPONSIVE ----------
const W = context?.width || 320;
const H = context?.height || 250;

const visibleRows = H < 230 ? 3 : 4;
const totalRows = rows.length;

const rowsForChart = [...rows];
const categories = rowsForChart.map(r => `${r.rank}`);
const values = rowsForChart.map(r => r.rechazos);

const maxVal = Math.max(...values, 1);
const labelAnchorValue = maxVal * 1.14;

const endPercent = totalRows <= visibleRows
  ? 100
  : Math.round((visibleRows / totalRows) * 100);

const rangoTxt =
  desdeVals.length && hastaVals.length
    ? `${fmtFechaHoraCorta(desdeVals[0])} - ${fmtFechaHoraCorta(hastaVals[0])}`
    : "ventana cerrada";

const filtroExtra = [
  cliente.nombre,
  selectedEst ? `Est. ${selectedEst}` : "Todos los est.",
  selectedMarca || "Todas las marcas"
].join(" · ");

// ---------- TOOLTIP ----------
function tooltipFormatter(params) {
  const r = rowsForChart[params.dataIndex];
  if (!r) return "";

  const detalleHtml = (r.detalles || [])
    .sort((a, b) => b.rechazos - a.rechazos)
    .map(d => `
      <tr>
        <td style="padding:2px 8px 2px 0;color:${textSoft}">${esc(labelMarca(d.marca))}</td>
        <td style="padding:2px 8px 2px 0;color:${textSoft}">${esc(d.codigo)}</td>
        <td style="padding:2px 8px 2px 0;color:${textSec}">${esc(d.origen)} / ${esc(d.tipo)}</td>
        <td style="padding:2px 0;text-align:right;color:${text};font-weight:800">${fmtNum(d.rechazos)}</td>
      </tr>
    `)
    .join("");

  return `
    <div style="min-width:320px;max-width:470px">
      <div style="font-weight:900;color:${r.color};margin-bottom:5px">
        ${r.rank}. ${esc(r.descripcion)}
      </div>

      <div style="color:${textSec};font-size:10.5px;margin-bottom:8px;line-height:1.4">
        ${esc(filtroExtra)}<br/>
        ${esc(rangoTxt)}
      </div>

      <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:9px">
        <span style="padding:3px 7px;border-radius:999px;background:rgba(255,255,255,0.06);color:${r.color};font-weight:800">
          ${esc(r.cuadrante)}
        </span>
        <span style="padding:3px 7px;border-radius:999px;background:rgba(255,255,255,0.06);color:${text}">
          ${fmtNum(r.rechazos)} rechazos
        </span>
        <span style="padding:3px 7px;border-radius:999px;background:rgba(255,255,255,0.06);color:${text}">
          ${fmtPct(r.pct)}
        </span>
      </div>

      <table style="width:100%;border-collapse:collapse;font-size:10.5px">
        <thead>
          <tr>
            <th style="text-align:left;color:${textSec};font-weight:700;padding-bottom:4px">Marca</th>
            <th style="text-align:left;color:${textSec};font-weight:700;padding-bottom:4px">Código</th>
            <th style="text-align:left;color:${textSec};font-weight:700;padding-bottom:4px">Origen</th>
            <th style="text-align:right;color:${textSec};font-weight:700;padding-bottom:4px">Tx</th>
          </tr>
        </thead>
        <tbody>
          ${detalleHtml}
        </tbody>
      </table>
    </div>
  `;
}

// ---------- RETURN ----------
return {
  backgroundColor: bg,

  title: {
    text: "Top causas 60m",
    subtext: `${fmtNum(total)} rechazos · ${rows.length} causas`,
    left: 10,
    top: 8,
    textStyle: {
      color: aqua,
      fontSize: 12,
      fontWeight: 800
    },
    subtextStyle: {
      color: textSec,
      fontSize: 9
    }
  },

  tooltip: {
    trigger: "item",
    appendToBody: false,
    confine: true,
    enterable: false,
    backgroundColor: "rgba(11,15,24,0.86)",
    borderColor: "rgba(0,244,196,0.55)",
    borderWidth: 1,
    padding: 9,
    textStyle: {
      color: text,
      fontSize: 11,
      fontFamily: "Inter, Roboto, sans-serif"
    },
    position: function (point, params, dom, rect, size) {
      const boxW = size.contentSize[0] || 320;
      const boxH = size.contentSize[1] || 180;
      const viewW = size.viewSize[0] || 320;
      const viewH = size.viewSize[1] || 240;

      let left = 24;
      let top = 48;

      if (left + boxW > viewW - 8) {
        left = Math.max(8, viewW - boxW - 8);
      }

      if (top + boxH > viewH - 8) {
        top = Math.max(8, viewH - boxH - 8);
      }

      return [left, top];
    },
    formatter: tooltipFormatter
  },

  grid: {
    left: 10,
    right: 44,
    top: 52,
    bottom: 12
  },

  xAxis: {
    type: "value",
    show: false,
    min: 0,
    max: labelAnchorValue
  },

  yAxis: {
    type: "category",
    data: categories,
    inverse: true,
    axisLine: { show: false },
    axisTick: { show: false },
