// ======================================================================================
// BUSINESS CHART — EVOLUCION 60M DE RECHAZOS POR CUADRANTE
// VERSION ROBUSTA + CODIGO DOMINANTE EN TOOLTIP
// Cliente + colores + catalogo unificado
// ======================================================================================

const aqua = "#00F4C4";
const amber = "#E7B432";
const violet = "#7C6AE6";
const coral = "#A9344D";
const slate = "#64748B";
const gray = "#94A3B8";
const blue = "#3B82F6";
const green = "#22C55E";

const bg = "#0a0e17";
const grid = "rgba(148,163,184,0.12)";
const text = "#E5E7EB";
const textSec = "#8b93a7";
const textSoft = "#CBD5E1";

const EMISOR_NO_CATALOGADO = "Emisor no catalogado";

const COLORS = {
  "Riesgo Emisor": violet,
  "Operativo Emisor": coral,
  "Riesgo Adquirente": aqua,
  "Operativo Adquirente": amber,
  "Emisor no catalogado": slate,
  "Otros": gray
};

const ORDER = [
  "Riesgo Emisor",
  "Operativo Emisor",
  "Riesgo Adquirente",
  "Operativo Adquirente",
  "Emisor no catalogado",
  "Otros"
];

const CLIENTES = {
  "30641405554": { nombre: "AEROLINEAS ARGENTINAS", color: green },
  "30503612891": { nombre: "BGH", color: green },
  "30663205621": { nombre: "CAJA DE SEGUROS", color: green },
  "30590360763": { nombre: "CENCOSUD", color: aqua },
  "30592845748": { nombre: "CETROGAR", color: amber },
  "30663288497": { nombre: "CLARO", color: blue },
  "30680743068": { nombre: "CLARO PAY", color: blue },
  "30525705931": { nombre: "COOPERATIVA OBRERA", color: aqua },
  "30548083156": { nombre: "COTO CICSA", color: aqua },
  "30638485733": { nombre: "DABRA SA", color: amber },
  "30718955722": { nombre: "DECATHLON", color: amber },
  "30516186670": { nombre: "DEHEZA SA", color: aqua },
  "30701307115": { nombre: "DESPEGAR", color: amber },
  "30711998612": { nombre: "DLP", color: amber },
  "30655116202": { nombre: "EDENOR", color: green },
  "30692138747": { nombre: "FARMACITY", color: aqua },
  "33707366589": { nombre: "FED. PATRONAL", color: green },
  "30526874249": { nombre: "FRAVEGA", color: amber },
  "30715621866": { nombre: "GMRA SA", color: amber },
  "30687310434": { nombre: "INC SA", color: amber },
  "30506730038": { nombre: "LA ANONIMA", color: aqua },
  "30703088534": { nombre: "MERCADO LIBRE", color: amber },
  "30532847547": { nombre: "MEGATONE", color: amber },
  "33707013139": { nombre: "MOSTAZA Y PAN", color: green },
  "30543659734": { nombre: "ON CITY", color: amber },
  "30711792186": { nombre: "PAGO VIRTUAL DEL SUR", color: violet },
  "30714407313": { nombre: "PAGOS360", color: violet },
  "30715221159": { nombre: "PAGOSYA", color: violet },
  "30695542476": { nombre: "PAN AMERICAN ENERGY", color: amber },
  "30708743514": { nombre: "PAYU", color: violet },
  "30707743987": { nombre: "PLUS PAGOS", color: violet },
  "30704950345": { nombre: "PROVINCIA NET", color: violet },
  "30659863789": { nombre: "SERV. ELECTRONICO DE PAGO", color: violet },
  "30612865333": { nombre: "VITAL", color: aqua },
  "30589621499": { nombre: "MAKRO", color: aqua },
  "30654855168": { nombre: "SWISS MEDICAL", color: green },
  "30640897267": { nombre: "TELECENTRO", color: blue },
  "30639453738": { nombre: "TELECOM", color: blue },
  "30678814357": { nombre: "MOVISTAR", color: blue },
  "33690765549": { nombre: "TICKETEK", color: green },
  "30715778722": { nombre: "TODOTRAIL", color: amber },
  "30716370964": { nombre: "VIUMI", color: amber },
  "30655534462": { nombre: "VISUAR", color: violet }
};

const GLOBAL_CLIENTE = { nombre: "PAYWAY GENERAL", color: textSoft };

// ---------- DATA ----------
const series = context.panel?.data?.series || [];
const s = series[0];

function valuesOfField(f) {
  if (!f) return [];
  if (typeof f.values?.toArray === "function") return f.values.toArray();
  return Array.from(f.values || []);
}

function fieldAny(names) {
  if (!s || !s.fields) return [];

  for (const name of names) {
    const f = s.fields.find(x =>
      String(x.name).toLowerCase() === String(name).toLowerCase()
    );

    const vals = valuesOfField(f);
    if (vals.length) return vals;
  }

  return [];
}

function num(v, d = 0) {
  const x = Number(v);
  return Number.isFinite(x) ? x : d;
}

function fmtNum(v) {
  return num(v).toLocaleString("es-AR");
}

function fmtPct(v) {
  return `${num(v).toFixed(1)}%`;
}

function fmtHora(v) {
  if (!v) return "—";

  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);

  return d.toLocaleTimeString("es-AR", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  });
}

function esc(v) {
  return String(v ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function normalizeBucket(v) {
  if (v == null || v === "") return null;

  const d = new Date(v);

  if (!isNaN(d.getTime())) {
    return d.toISOString();
  }

  return String(v);
}

function normalizeQuadrant(v) {
  const raw = String(v ?? "").trim();
  if (!raw) return "Otros";
  if (ORDER.includes(raw)) return raw;

  const x = raw.toUpperCase();

  if (x === "RIESGO EMISOR") return "Riesgo Emisor";
  if (x === "OPERATIVO EMISOR") return "Operativo Emisor";
  if (x === "RIESGO ADQUIRENTE") return "Riesgo Adquirente";
  if (x === "OPERATIVO ADQUIRENTE") return "Operativo Adquirente";
  if (x === "EMISOR NO CATALOGADO") return EMISOR_NO_CATALOGADO;
  if (x === "CODIGO EMISOR DE OTRAS MARCAS") return EMISOR_NO_CATALOGADO;
  if (x === "CÓDIGO EMISOR DE OTRAS MARCAS") return EMISOR_NO_CATALOGADO;
  if (x === "CODIGO EMISOR - MARCA NO MAPEADA") return EMISOR_NO_CATALOGADO;
  if (x === "CÓDIGO EMISOR - MARCA NO MAPEADA") return EMISOR_NO_CATALOGADO;
  if (x === "ISSUER NO MAPEADO") return EMISOR_NO_CATALOGADO;
  if (x === "EMISOR NO MAPEADO") return EMISOR_NO_CATALOGADO;
  if (x === "OTROS") return "Otros";
  if (x === "NO CLASIFICADO") return "Otros";

  return raw;
}

function prettyMarca(v) {
  const x = String(v ?? "-").toUpperCase();

  const map = {
    VISA: "Visa",
    MASTERCARD: "Mastercard",
    AMEX: "Amex",
    CABAL_DISCOVER: "Cabal / Discover",
    CABAL: "Cabal / Discover",
    DISCOVER: "Cabal / Discover",
    UPI: "UPI",
    OTRAS: "Otras",
    OTRA: "Otras",
    "-": "-"
  };

  return map[x] || v;
}

function prettyCodigo(v) {
  const x = String(v ?? "-").trim();

  if (!x || x === "-") return "-";
  if (x === "SIN_DESC") return "Sin catalogo";
  if (x === "SIN_CODIGO") return "S/C";

  return x;
}

// ---------- VARIABLES GRAFANA ----------
function rv(str) {
  try {
    if (context?.grafana?.replaceVariables) {
      return context.grafana.replaceVariables(str);
    }
  } catch (e) { }
  return str;
}

function cleanValue(v) {
  const x = String(v ?? "").trim();

  if (!x) return null;
  if (x === "-1") return null;
  if (x.toUpperCase() === "ALL") return null;
  if (x.toUpperCase() === "TODAS LAS MARCAS") return null;

  return x;
}

function noHayRechazos() {
  return {
    backgroundColor: bg,
    graphic: [
      {
        type: "text",
        left: 12,
        top: 8,
        style: {
          text: "Evolucion 60m por cuadrante",
          fill: aqua,
          font: "800 12px sans-serif"
        },
        silent: true
      },
      {
        type: "text",
        left: "center",
        top: "middle",
        style: {
          text: "No hay rechazos",
          fill: textSec,
          font: "800 12px sans-serif",
          textAlign: "center"
        },
        silent: true
      }
    ],
    xAxis: { show: false },
    yAxis: { show: false },
    series: [],
    animation: false
  };
}

const selectedEst = cleanValue(rv("${establecimiento:raw}"));
const selectedMarcaRaw = cleanValue(rv("${marca:raw}"));
const selectedMarca = selectedMarcaRaw ? prettyMarca(selectedMarcaRaw) : null;

const selectedClienteRaw =
  cleanValue(rv("${cuit:raw}")) ||
  cleanValue(rv("${cuit:label}"));

let cliente = GLOBAL_CLIENTE;

if (selectedClienteRaw) {
  const cuitNorm = String(selectedClienteRaw).replace(/[^0-9]/g, "");
  cliente = CLIENTES[cuitNorm] || { nombre: `CUIT ${cuitNorm}`, color: textSoft };
}

// ---------- EMPTY REAL ----------
if (!s || !s.fields || s.fields.length === 0) {
  return noHayRechazos();
}

// ---------- CAMPOS ----------
const bucketsRaw = fieldAny([
  "bucket_utc",
  "bucket",
  "minuto_utc",
  "time",
  "timestamp"
]);

const cuadrantesRaw = fieldAny([
  "cuadrante",
  "quadrant",
  "cuadrante_mapeado"
]);

const rechazosRaw = fieldAny([
  "rechazos",
  "denegadas",
  "total_denegadas",
  "count",
  "cantidad",
  "total_rechazos",
  "rechazos_codigo"
]);

const codigosDomRaw = fieldAny(["codigo_dominante"]);
const marcasDomRaw = fieldAny(["marca_dominante"]);
const origenDomRaw = fieldAny(["origen_codigo_dominante"]);
const tipoDomRaw = fieldAny(["tipo_codigo_dominante"]);
const rechazosCodigoDomRaw = fieldAny(["rechazos_codigo_dominante"]);
const pctCodigoDomRaw = fieldAny(["pct_codigo_dominante"]);

if (!bucketsRaw.length || !cuadrantesRaw.length || !rechazosRaw.length) {
  return noHayRechazos();
}

// ---------- NORMALIZACION ----------
const bucketSet = new Set();
const matrix = {};
const details = {};

for (let i = 0; i < bucketsRaw.length; i++) {
  const bucket = normalizeBucket(bucketsRaw[i]);
  const cuadrante = normalizeQuadrant(cuadrantesRaw[i]);
  const rechazos = num(rechazosRaw[i], 0);

  if (bucket == null) continue;

  const codigoDom = String(codigosDomRaw[i] ?? "-");
  const marcaDom = String(marcasDomRaw[i] ?? "-");
  const origenDom = String(origenDomRaw[i] ?? "-");
  const tipoDom = String(tipoDomRaw[i] ?? "-");
  const rechazosCodigoDom = num(rechazosCodigoDomRaw[i], 0);
  const pctCodigoDom = num(pctCodigoDomRaw[i], 0);

  bucketSet.add(bucket);

  if (!matrix[bucket]) matrix[bucket] = {};
  if (!details[bucket]) details[bucket] = {};

  matrix[bucket][cuadrante] = (matrix[bucket][cuadrante] || 0) + rechazos;

  details[bucket][cuadrante] = {
    codigo: codigoDom,
    marca: marcaDom,
    origen: origenDom,
    tipo: tipoDom,
    rechazosCodigo: rechazosCodigoDom,
    pctCodigo: pctCodigoDom
  };
}

const buckets = Array.from(bucketSet).sort((a, b) => new Date(a) - new Date(b));

const totalRechazos = buckets.reduce((acc, b) => {
  return acc + ORDER.reduce((suma, q) => suma + num(matrix[b]?.[q], 0), 0);
}, 0);

if (!buckets.length || totalRechazos === 0) {
  return noHayRechazos();
}

const maxBucket = buckets.reduce((max, b) => {
  const totalBucket = ORDER.reduce((suma, q) => suma + num(matrix[b]?.[q], 0), 0);
  return Math.max(max, totalBucket);
}, 0);

const activeQuadrants = ORDER.filter(q =>
  buckets.some(b => num(matrix[b]?.[q], 0) > 0)
);

const quadrantsToShow = activeQuadrants.length ? activeQuadrants : ORDER;

// ---------- SERIES ----------
const chartSeries = quadrantsToShow.map(q => ({
  name: q,
  type: "line",
  stack: "rechazos",
  smooth: 0.32,
  symbol: "none",
  areaStyle: {
    opacity: 0.20
  },
  lineStyle: {
    width: 1.5
  },
  emphasis: {
    focus: "series"
  },
  itemStyle: {
    color: COLORS[q] || slate
  },
  data: buckets.map(b => [b, num(matrix[b]?.[q], 0)])
}));

// ---------- RANGO ----------
const firstBucket = buckets.length ? buckets[0] : null;
const lastBucket = buckets.length ? buckets[buckets.length - 1] : null;

const rangoTxt =
  firstBucket && lastBucket
    ? `${fmtHora(firstBucket)} - ${fmtHora(lastBucket)}`
    : "—";

const chips = [];

chips.push(cliente.nombre);
if (selectedEst) chips.push(`Est. ${selectedEst}`);
if (selectedMarca) chips.push(selectedMarca);

const filtroTxt = chips.join(" · ");

// ---------- TOOLTIP ----------
function tooltipFormatter(params) {
  const arr = Array.isArray(params) ? params : [params];

  if (!arr.length) return "";

  const bucketRaw = arr[0]?.value?.[0] ?? arr[0]?.axisValue;
  const bucket = normalizeBucket(bucketRaw);

  const rows = arr
    .filter(p => num(p.value?.[1], 0) > 0)
    .sort((a, b) => num(b.value?.[1], 0) - num(a.value?.[1], 0));

  const total = arr.reduce((acc, p) => acc + num(p.value?.[1], 0), 0);

  const lines = rows.length
    ? rows.map(p => {
      const cuadrante = p.seriesName;
      const val = num(p.value?.[1], 0);
      const pct = total > 0 ? (val * 100) / total : 0;

      const d = details[bucket]?.[cuadrante] || {};
      const codigo = prettyCodigo(d.codigo);
      const marca = prettyMarca(d.marca);
      const rechCodigo = num(d.rechazosCodigo, 0);
      const pctCodigo = num(d.pctCodigo, 0);
      const origen = String(d.origen ?? "-");
      const tipo = String(d.tipo ?? "-");

      const dominanteHtml =
        codigo !== "-" && codigo !== "S/C"
          ? `
              <div style="margin-left:15px;margin-top:3px;color:${textSec};font-size:10.5px;line-height:1.35;">
                Dominante:
                <b style="color:${textSoft}">${esc(codigo)}</b>
                <span style="color:${textSec}"> · ${esc(marca)}</span>
                ${pctCodigo > 0 ? `<span style="color:${textSec}"> · ${fmtPct(pctCodigo)}</span>` : ""}
                ${rechCodigo > 0 ? `<span style="color:${textSec}"> · ${fmtNum(rechCodigo)} rech.</span>` : ""}
                <br/>
                <span style="color:${textSec}">${esc(origen)} / ${esc(tipo)}</span>
              </div>
            `
          : `
              <div style="margin-left:15px;margin-top:3px;color:${textSec};font-size:10.5px;line-height:1.35;">
                Dominante:
                <b style="color:${textSoft}">sin codigo</b>
              </div>
            `;

      return `
          <div style="margin:6px 0">
            <div style="display:flex;justify-content:space-between;gap:14px;margin:3px 0">
              <span>
                <span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:${p.color};margin-right:6px;"></span>
                ${esc(cuadrante)}
              </span>
              <b>${fmtNum(val)} · ${pct.toFixed(1)}%</b>
            </div>
            ${dominanteHtml}
          </div>
        `;
    }).join("")
    : `<div style="color:${textSec};margin-top:6px">No hay rechazos</div>`;

  return `
    <div style="min-width:300px;max-width:430px">
      <div style="font-weight:800;color:${text};margin-bottom:5px">${fmtHora(bucket)}</div>
      <div style="color:${textSec};font-size:11px;margin-bottom:7px">
        ${esc(filtroTxt)}<br/>
        Total rechazos: <b style="color:${text}">${fmtNum(total)}</b>
      </div>
      ${lines}
    </div>
  `;
}

// ---------- GRAPHICS ----------
const graphics = [];

graphics.push({
  type: "text",
  left: 12,
  top: 8,
  style: {
    text: "Ultimos 60m",
    fill: aqua,
    font: "bold 13px sans-serif"
  },
  silent: true
});

graphics.push({
  type: "text",
  left: 12,
  top: 25,
  style: {
    text: `${rangoTxt} · ventana cerrada`,
    fill: textSec,
    font: "10px sans-serif"
  },
  silent: true
});

graphics.push({
  type: "text",
  right: 16,
  top: 8,
  style: {
    text: filtroTxt,
    fill: cliente.color,
    font: "10px sans-serif",
    textAlign: "right"
  },
  silent: true
});

if (maxBucket > 0) {
  graphics.push({
    type: "text",
    right: 16,
    top: 25,
    style: {
      text: `Pico max: ${fmtNum(maxBucket)}`,
      fill: textSec,
      font: "10px sans-serif",
      textAlign: "right"
    },
    silent: true
  });
}

return {
  backgroundColor: bg,

  title: {
    text: "Evolucion de rechazos por cuadrante",
    left: 12,
    top: 43,
    textStyle: {
      color: text,
      fontSize: 12,
      fontWeight: 800
    }
  },

  legend: {
    top: 65,
    left: 12,
    itemWidth: 7,
    itemHeight: 7,
    icon: "circle",
    itemGap: 9,
    textStyle: {
      color: textSec,
      fontSize: 8.5
    },
    data: quadrantsToShow
  },

  tooltip: {
    trigger: "axis",
    appendToBody: false,
    confine: true,
    enterable: false,
    backgroundColor: "rgba(11,15,24,0.78)",
    borderColor: "rgba(0,244,196,0.55)",
    borderWidth: 1,
    padding: 9,
    textStyle: {
      color: text,
      fontSize: 11,
      fontFamily: "Inter, Roboto, sans-serif"
    },
    axisPointer: {
      type: "line",
      lineStyle: {
        color: "rgba(255,255,255,0.22)",
        width: 1
      }
    },
    position: function (point, params, dom, rect, size) {
      const boxW = size.contentSize[0] || 320;
      const boxH = size.contentSize[1] || 180;
      const viewW = size.viewSize[0] || 500;
      const viewH = size.viewSize[1] || 240;

      let left = point[0] + 24;
      let top = point[1] - boxH / 2;

      if (left + boxW > viewW - 8) left = point[0] - boxW - 14;
      if (left < 8) left = 8;
      if (top < 8) top = 8;
      if (top + boxH > viewH - 8) top = Math.max(8, viewH - boxH - 8);

      return [left, top];
    },
    formatter: tooltipFormatter
  },

  grid: {
    left: 40,
    right: 18,
    top: 96,
    bottom: 24
  },

  xAxis: {
    type: "time",
    boundaryGap: false,
    axisLine: {
      lineStyle: {
        color: "rgba(148,163,184,0.16)"
      }
    },
    axisTick: { show: false },
    axisLabel: {
      color: textSec,
      fontSize: 8.5,
      margin: 10,
      formatter: value => fmtHora(value)
    },
    splitLine: { show: false }
  },

  yAxis: {
    type: "value",
    minInterval: 1,
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: {
      color: textSec,
      fontSize: 8.5,
      formatter: value => fmtNum(value)
    },
    splitLine: {
      lineStyle: { color: grid }
    }
  },

  graphic: graphics,
  series: chartSeries,
  animation: false
};

