    .replace(/DistribuciÃ³n/g, "Distribucion")
    .replace(/relaciÃ³n/g, "relacion")
    .replace(/RelaciÃ³n/g, "Relacion")
    .replace(/Ã¡/g, "a")
    .replace(/Ã©/g, "e")
    .replace(/Ã­/g, "i")
    .replace(/Ã³/g, "o")
    .replace(/Ãº/g, "u")
    .replace(/Ã±/g, "n")
    .replace(/Ã/g, "A")
    .replace(/Ã‰/g, "E")
    .replace(/Ã/g, "I")
    .replace(/Ã“/g, "O")
    .replace(/Ãš/g, "U")
    .replace(/Ã‘/g, "N")
    .replace(/Â/g, "")
    .replace(/â€“/g, "-")
    .replace(/â€”/g, "-")
    .replace(/â€œ/g, '"')
    .replace(/â€/g, '"')
    .replace(/â€˜/g, "'")
    .replace(/â€™/g, "'");
}

function short(v, max = 70) {
  const t = cleanText(v);
  return t.length > max ? `${t.slice(0, max - 1)}...` : t;
}

function fmtFechaHora(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);

  const fecha = d.toLocaleDateString("es-AR", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric"
  });

  const hora = d.toLocaleTimeString("es-AR", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  });

  return `${fecha} ${hora}`;
}

function fmtFechaHoraCorta(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);

  const fecha = d.toLocaleDateString("es-AR", {
    day: "2-digit",
    month: "2-digit"
  });

  const hora = d.toLocaleTimeString("es-AR", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  });

  return `${fecha} ${hora}`;
}

function prettyMarca(v) {
  const x = cleanText(v || "-1").toUpperCase();

  if (x === "-1" || x === "ALL" || x === "TODAS LAS MARCAS" || x === "SIN_RECHAZOS") {
    return "Todas las marcas";
  }

  const map = {
    VISA: "Visa",
    MASTERCARD: "Mastercard",
    AMEX: "Amex",
    CABAL_DISCOVER: "Cabal / Discover",
    CABAL: "Cabal / Discover",
    DISCOVER: "Cabal / Discover",
    UPI: "UPI",
    OTRAS: "Otras",
    OTRA: "Otras",
    GENERAL: "General"
  };

  return map[x] || x;
}

function prettyEst(v) {
  const x = cleanText(v || "-1").trim();

  if (!x || x === "-1" || x.toUpperCase() === "ALL" || x.toUpperCase() === "SIN_RECHAZOS") {
    return "Todos los est.";
  }

  return `Est. ${x}`;
}

function normalizeCuadrante(v) {
  const raw = cleanText(v ?? "Otros").trim();
  const upper = raw.toUpperCase();

  if (COLORS[raw]) return raw;

  if (upper === "RIESGO EMISOR") return "Riesgo Emisor";
  if (upper === "OPERATIVO EMISOR") return "Operativo Emisor";
  if (upper === "RIESGO ADQUIRENTE") return "Riesgo Adquirente";
  if (upper === "OPERATIVO ADQUIRENTE") return "Operativo Adquirente";
  if (upper === "EMISOR NO CATALOGADO") return "Emisor no catalogado";
  if (upper === "CODIGO EMISOR DE OTRAS MARCAS") return "Emisor no catalogado";
  if (upper === "CODIGO EMISOR - MARCA NO MAPEADA") return "Emisor no catalogado";
  if (upper === "ISSUER NO MAPEADO") return "Emisor no catalogado";
  if (upper === "EMISOR NO MAPEADO") return "Emisor no catalogado";
  if (upper === "OTROS") return "Otros";
  if (upper === "SIN RECHAZOS") return "Sin rechazos";

  return raw || "Otros";
}

function rv(str) {
  try {
    if (context?.grafana?.replaceVariables) {
      return context.grafana.replaceVariables(str);
    }
  } catch (e) { }
  return str;
}

function cleanValue(v) {
  const x = String(v ?? "").trim();

  if (!x) return null;
  if (x === "-1") return null;
  if (x.toUpperCase() === "ALL") return null;
  if (x.toUpperCase() === "TODAS LAS MARCAS") return null;

  return x;
}

// ---------- EMPTY ----------
if (!s || !s.fields || s.fields.length === 0) {
  return {
    backgroundColor: bg,
    graphic: [{
      type: "text",
      left: "center",
      top: "middle",
      style: {
        text: "Sin datos para visualizar",
        fill: textSec,
        font: "600 12px sans-serif"
      }
    }],
    xAxis: { show: false },
    yAxis: { show: false },
    series: [],
    animation: false
  };
}

// ---------- CAMPOS ----------
const totalTx = num(firstAny(["total_tx"], 0), 0);
const denegadas = num(firstAny(["denegadas", "total_denegadas"], 0), 0);
const tasaRechazo = num(firstAny(["tasa_rechazo_pct"], 0), 0);

const rangoDesdeRaw = firstAny(["rango_desde", "desde"], null);
const rangoHastaRaw = firstAny(["rango_hasta", "hasta"], null);

const cuitRaw = firstAny(["cuit"], "-1");
const marcaFiltroRaw = firstAny(["marca_filtro", "marca_param", "marca"], "-1");
const establecimientoFiltroRaw = firstAny(["establecimiento_filtro", "establecimiento_param", "establecimiento"], "-1");

const marcasRaw = fieldAny(["marca"]);
const cuadrantesRaw = fieldAny(["cuadrante"]);
const causasRaw = fieldAny(["causa", "descripcion", "descripcion_codigo"]);
const origenesRaw = fieldAny(["origen_codigo"]);
const tiposRaw = fieldAny(["tipo_codigo"]);
const codigosRaw = fieldAny(["codigo_detalle", "codigo", "codigos_asociados"]);
const causaTxRaw = fieldAny(["causa_tx", "rechazos", "value"]);
const causaPctDenegRaw = fieldAny(["causa_pct_deneg", "pct_denegadas"]);
const causaPctTotalRaw = fieldAny(["causa_pct_total", "pct_total"]);

if (!causasRaw.length || !causaTxRaw.length) {
  return {
    backgroundColor: bg,
    title: {
      text: "Distribucion de rechazos",
      subtext: "Faltan campos esperados",
      left: 12,
      top: 8,
      textStyle: {
        color: aqua,
        fontSize: 12,
        fontWeight: 800
      },
      subtextStyle: {
        color: textSec,
        fontSize: 9
      }
    },
    graphic: [{
      type: "text",
      left: "center",
      top: "middle",
      style: {
        text:
          "Esperados: causa, causa_tx\n\nRecibidos:\n" +
          allFieldNames(),
        fill: textSec,
        font: "600 10px sans-serif",
        width: 420,
        overflow: "break",
        textAlign: "center"
      }
    }],
    xAxis: { show: false },
    yAxis: { show: false },
    series: [],
    animation: false
  };
}

// ---------- CLIENTE / FILTROS ----------
let cliente = GLOBAL_CLIENTE;

const selectedClienteRaw =
  cleanValue(rv("${cuit:raw}")) ||
  cleanValue(rv("${cuit:label}"));

if (selectedClienteRaw) {
  const c = String(selectedClienteRaw).replace(/[^0-9]/g, "");
  if (CLIENTES[c]) {
    cliente = CLIENTES[c];
  } else if (c && c !== "1" && c !== "-1") {
    cliente = { nombre: `CUIT ${c}`, color: textSoft };
  }
} else {
  const c = String(cuitRaw ?? "-1").replace(/[^0-9]/g, "");
  if (c && c !== "1" && c !== "-1") {
    cliente = CLIENTES[c] || { nombre: `CUIT ${c}`, color: textSoft };
  }
}

const selectedEst =
  cleanValue(rv("${establecimiento:raw}")) ||
  cleanValue(String(establecimientoFiltroRaw ?? ""));

const selectedMarcaRaw =
  cleanValue(rv("${marca:raw}")) ||
  cleanValue(String(marcaFiltroRaw ?? ""));

const marcaVisible = selectedMarcaRaw ? prettyMarca(selectedMarcaRaw) : prettyMarca(marcaFiltroRaw);
const estVisible = selectedEst ? `Est. ${selectedEst}` : prettyEst(establecimientoFiltroRaw);

const rangoTxt =
  rangoDesdeRaw && rangoHastaRaw
    ? `${fmtFechaHoraCorta(rangoDesdeRaw)} - ${fmtFechaHoraCorta(rangoHastaRaw)}`
    : "rango seleccionado";

const rangoTooltip =
  rangoDesdeRaw && rangoHastaRaw
    ? `${fmtFechaHora(rangoDesdeRaw)} - ${fmtFechaHora(rangoHastaRaw)}`
    : "rango seleccionado";

const filtroTxt = [
  cliente.nombre,
  estVisible,
  marcaVisible
].join(" · ");

// ---------- DATA NORMALIZADA ----------
let rowsRaw = [];

for (let i = 0; i < causasRaw.length; i++) {
  const value = num(causaTxRaw[i], 0);
  const causa = short(causasRaw[i] ?? "Sin causa", 120);
  const cuadrante = normalizeCuadrante(cuadrantesRaw[i] ?? "Otros");

  rowsRaw.push({
    marca: prettyMarca(marcasRaw[i] ?? "General"),
    cuadrante,
    causa,
    origen: cleanText(origenesRaw[i] ?? "-"),
    tipo: cleanText(tiposRaw[i] ?? "-"),
    codigo: cleanText(codigosRaw[i] ?? "-"),
    value,
    pctDeneg: num(causaPctDenegRaw[i], denegadas > 0 ? (100 * value / denegadas) : 0),
    pctTotal: num(causaPctTotalRaw[i], totalTx > 0 ? (100 * value / totalTx) : 0)
  });
}

let rows = rowsRaw
  .filter(r => r.value > 0 || denegadas === 0)
  .sort((a, b) => b.value - a.value);

if (!rows.length) {
  rows = [{
    marca: "General",
    cuadrante: "Sin rechazos",
    causa: "Sin rechazos en el rango",
    origen: "-",
    tipo: "-",
    codigo: "-",
    value: 0,
    pctDeneg: 0,
    pctTotal: 0
  }];
}

// ---------- AGRUPACION POR CAUSA ----------
const groupedMap = new Map();

rows.forEach(r => {
  const key = r.causa;

  if (!groupedMap.has(key)) {
    groupedMap.set(key, {
      causa: r.causa,
      total: 0,
      pctDeneg: 0,
      pctTotal: 0,
      marcas: new Set(),
      detalles: []
    });
  }

  const item = groupedMap.get(key);
  item.total += r.value;
  item.pctDeneg += r.pctDeneg;
  item.pctTotal += r.pctTotal;
  item.marcas.add(r.marca);
  item.detalles.push(r);
});

const grouped = Array.from(groupedMap.values())
  .sort((a, b) => b.total - a.total);

const labels = grouped.map(x => x.causa);

const totalByCuadrante = rows.reduce((acc, r) => {
  acc[r.cuadrante] = (acc[r.cuadrante] ?? 0) + r.value;
  return acc;
}, {});

const quadrants = ORDER.filter(q => (totalByCuadrante[q] ?? 0) > 0);
const activeQuadrants = quadrants.length ? quadrants : ["Sin rechazos"];

// ---------- SERIES ----------
const chartSeries = activeQuadrants.map(q => ({
  name: q,
  type: "bar",
  stack: "rechazos",
  barWidth: 14,
  clip: true,
  z: 2,
  emphasis: {
    focus: "series"
  },
  itemStyle: {
    color: COLORS[q] || slate,
    borderRadius: [0, 5, 5, 0]
  },
  data: labels.map(label => {
    const details = rows.filter(
      r => r.causa === label && r.cuadrante === q
    );

    const value = details.reduce((a, r) => a + r.value, 0);
    const pctDeneg = details.reduce((a, r) => a + r.pctDeneg, 0);
    const pctTotal = details.reduce((a, r) => a + r.pctTotal, 0);
    const marcas = [...new Set(details.map(r => r.marca))].join(", ");

    if (value === 0) return 0;

    return {
      value,
      causa: label,
      cuadrante: q,
      pctDeneg,
      pctTotal,
      marcas,
      details
    };
  })
}));

// ---------- LAYOUT RESPONSIVE ----------
const W = context?.width || 900;
const H = context?.height || 360;

const isSmall = W < 650 || H < 300;
const isMedium = W >= 650 && W < 900;

const headerH = isSmall ? 100 : 108;
const legendTop = isSmall ? 72 : 78;
const topGrid = isSmall ? 112 : 122;
const bottomGrid = labels.length > 5 ? 34 : 24;

const availableChartH = Math.max(90, H - topGrid - bottomGrid);
const rowH = isSmall ? 24 : 26;
const showRows = Math.max(3, Math.floor(availableChartH / rowH));
const needScroll = labels.length > showRows;

const dzEnd = labels.length
  ? Math.min(100, (showRows / labels.length) * 100)
  : 100;

const leftGrid = W < 650 ? 210 : W < 900 ? 280 : 340;
const labelWidth = Math.max(150, leftGrid - 34);
const topCause = grouped[0];

const graphics = [];

// ---------- HEADER ----------
graphics.push({
  type: "text",
  left: 12,
  top: 8,
  z: 100,
  style: {
    text: "Distribucion de rechazos",
    fill: aqua,
    font: `800 ${isSmall ? 11.5 : 13}px sans-serif`
  },
  silent: true
});

graphics.push({
  type: "text",
  left: 12,
  top: isSmall ? 25 : 27,
  z: 100,
  style: {
    text: `${fmtShort(totalTx)} tx · ${fmtShort(denegadas)} denegadas · ${fmtPct(tasaRechazo, 1)} rechazo`,
    fill: textSec,
    font: `600 ${isSmall ? 8.5 : 9.5}px sans-serif`
  },
  silent: true
});

graphics.push({
  type: "text",
  right: 12,
  top: 8,
  z: 100,
  style: {
    text: rangoTxt,
    fill: textSec,
    font: `700 ${isSmall ? 8.5 : 9.5}px sans-serif`,
    textAlign: "right"
  },
  silent: true
});

graphics.push({
  type: "text",
  right: 12,
  top: isSmall ? 25 : 27,
  z: 100,
  style: {
    text: short(filtroTxt, W < 650 ? 36 : W < 900 ? 52 : 82),
    fill: cliente.color,
    font: `800 ${isSmall ? 8.5 : 9.5}px sans-serif`,
    textAlign: "right"
  },
  silent: true
});

if (topCause && topCause.total > 0) {
  const peso = denegadas > 0 ? (100 * topCause.total / denegadas) : 0;

  graphics.push({
    type: "text",
    left: 12,
    top: isSmall ? 45 : 48,
    z: 100,
    style: {
      text: `Principal: ${short(topCause.causa, W < 650 ? 34 : W < 900 ? 50 : 78)} · ${fmtShort(topCause.total)} rech. · ${fmtPct(peso, 1)}`,
      fill: textSoft,
      font: `700 ${isSmall ? 8.5 : 9.5}px sans-serif`
    },
    silent: true
  });
}

if (needScroll) {
  graphics.push({
    type: "text",
    right: 12,
    bottom: 3,
    z: 100,
    style: {
      text: "scroll para ver mas causas",
      fill: textSec,
      font: "700 8.5px sans-serif",
      textAlign: "right"
    },
    silent: true
  });
}

// ---------- TOOLTIP ----------
function tooltipFormatter(p) {
  if (!p?.data || typeof p.data === "number") return "";

  const d = p.data;
  const details = d.details ?? [];

  const lines = details
    .sort((a, b) => b.value - a.value)
    .slice(0, 8)
    .map(r => `
      <tr>
        <td style="padding:2px 8px 2px 0;color:${textSoft}">
          ${esc(r.marca)}
        </td>
        <td style="padding:2px 8px;color:${textSoft}">
          ${esc(r.codigo)}
        </td>
        <td style="padding:2px 8px;color:${textSec}">
          ${esc(r.origen)} / ${esc(r.tipo)}
        </td>
        <td style="padding:2px 0;text-align:right;color:${text}">
          ${fmtNum(r.value)}
        </td>
      </tr>
    `)
    .join("");

  return `
    <div style="min-width:330px;max-width:540px;line-height:1.38">
      <div style="font-size:13px;font-weight:900;color:${COLORS[d.cuadrante] || aqua};margin-bottom:5px">
        ${esc(d.causa)}
      </div>

      <div style="color:${cliente.color};font-weight:800;font-size:11px;margin-bottom:3px">
        ${esc(cliente.nombre)}
      </div>

      <div style="color:${textSec};font-size:10.5px;margin-bottom:8px">
        ${esc(estVisible)} · ${esc(marcaVisible)}<br/>
        ${esc(rangoTooltip)}
      </div>

      <div style="display:flex;gap:7px;flex-wrap:wrap;margin-bottom:9px">
        <span style="
          border:1px solid ${COLORS[d.cuadrante] || border};
          color:${COLORS[d.cuadrante] || text};
          border-radius:999px;
          padding:2px 8px;
          font-size:10.5px;
          font-weight:800;
        ">
          ${esc(d.cuadrante)}
        </span>

        <span style="
          border:1px solid ${border};
          color:${textSoft};
          border-radius:999px;
          padding:2px 8px;
          font-size:10.5px;
        ">
          ${fmtNum(d.value)} rechazos
        </span>

        <span style="
          border:1px solid ${border};
          color:${textSoft};
          border-radius:999px;
          padding:2px 8px;
          font-size:10.5px;
        ">
          ${fmtPct(d.pctDeneg, 1)} de denegadas
        </span>
      </div>

      <table style="width:100%;border-collapse:collapse;font-size:10.5px">
        <thead>
          <tr style="color:${textSec};text-align:left">
            <th style="padding:0 8px 5px 0">Marca</th>
            <th style="padding:0 8px 5px 8px">Codigo</th>
            <th style="padding:0 8px 5px 8px">Origen</th>
            <th style="padding:0 0 5px 8px;text-align:right">Tx</th>
          </tr>
        </thead>
        <tbody>
          ${lines || `
            <tr>
              <td colspan="4" style="color:${textSec};padding-top:4px">
                Sin detalle disponible
              </td>
            </tr>
          `}
        </tbody>
      </table>
    </div>
  `;
}

// ---------- RETURN ----------
return {
  backgroundColor: bg,

  legend: {
    top: legendTop,
    z: 100,
    left: 12,
    itemWidth: 7,
    itemHeight: 7,
    icon: "circle",
    itemGap: isSmall ? 7 : 10,
    textStyle: {
      color: textSec,
      fontSize: isSmall ? 7.8 : 8.5
    },
    data: activeQuadrants
  },

  tooltip: {
    trigger: "item",
    appendToBody: true,
    confine: true,
    enterable: false,
    backgroundColor: "rgba(8,13,24,0.96)",
    borderColor: aqua,
    borderWidth: 1,
    padding: 10,
    textStyle: {
      color: text,
      fontSize: 11,
      fontFamily: "Inter, Roboto, sans-serif"
    },
    position: function (point, params, dom, rect, size) {
      const boxW = size.contentSize[0] || 360;
      const boxH = size.contentSize[1] || 220;
      const viewW = size.viewSize[0] || W;
      const viewH = size.viewSize[1] || H;

      let left = point[0] + 16;
      let top = point[1] - boxH / 2;

      if (left + boxW > viewW - 8) left = point[0] - boxW - 16;
      if (left < 8) left = 8;
      if (top < 8) top = 8;
      if (top + boxH > viewH - 8) top = Math.max(8, viewH - boxH - 8);

      return [left, top];
    },
    formatter: tooltipFormatter
  },

  grid: {
    left: leftGrid,
    right: needScroll ? 36 : 18,
    top: topGrid,
    bottom: bottomGrid
  },

  xAxis: {
    type: "value",
    minInterval: 1,
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: {
      color: textSec,
      fontSize: isSmall ? 7.8 : 8.5,
      formatter: value => fmtShort(value)
    },
    splitLine: {
      lineStyle: { color: grid }
    }
  },

  yAxis: {
    type: "category",
    inverse: true,
    data: labels,
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: {
      color: textSoft,
      fontSize: isSmall ? 8.5 : 9.5,
      interval: 0,
      width: labelWidth,
      overflow: "truncate",
      align: "right",
      padding: [0, 10, 0, 0],
      formatter: value => short(value, W < 650 ? 34 : W < 900 ? 55 : 72),
      hideOverlap: true,
      margin: 12
    }
  },

  dataZoom: needScroll
    ? [
      {
        type: "inside",
        yAxisIndex: 0,
        filterMode: "weakFilter",
        zoomOnMouseWheel: false,
        moveOnMouseWheel: true,
        moveOnMouseMove: true,
        start: 0,
        end: dzEnd
      },
      {
        type: "slider",
        yAxisIndex: 0,
        right: 7,
        width: 9,
        top: topGrid,
        bottom: bottomGrid,
        borderColor: border,
        fillerColor: "rgba(0,244,196,0.18)",
        handleSize: 0,
        showDetail: false,
        showDataShadow: false,
        backgroundColor: "rgba(148,163,184,0.06)",
        start: 0,
        end: dzEnd
      }
    ]
    : [],

  series: chartSeries,
  graphic: graphics,
  animation: false
};

