  "30655534462": { nombre: "VISUAR", color: violet }
};

const GLOBAL_CLIENTE = { nombre: "PAYWAY GENERAL", color: textSoft };

const series = context.panel?.data?.series || [];
const s = series[0];

function valuesOfField(f) {
  if (!f) return [];
  if (typeof f.values?.toArray === "function") return f.values.toArray();
  return Array.from(f.values || []);
}

function normName(v) {
  return String(v ?? "").trim().toLowerCase();
}

function fieldAny(names) {
  if (!s || !s.fields) return [];
  const wanted = names.map(normName);
  for (const f of s.fields) {
    if (wanted.includes(normName(f.name))) return valuesOfField(f);
  }
  return [];
}

function firstAny(names, fallback = null) {
  const vals = fieldAny(names);
  return vals.length ? vals[0] : fallback;
}

function num(v, d = 0) {
  const x = Number(v);
  return Number.isFinite(x) ? x : d;
}

function fmtNum(v) {
  return num(v).toLocaleString("es-AR");
}

function fmtShort(v) {
  const n = num(v, 0);
  if (n >= 1000000) return `${(n / 1000000).toFixed(2)}M`;
  if (n >= 1000) return `${(n / 1000).toFixed(1)}k`;
  return fmtNum(n);
}

function fmtPct(v, d = 1) {
  const x = num(v);
  if (x === 100) return "100%";
  return `${x.toFixed(d)}%`;
}

function fmtMs(v) {
  const x = Number(v);
  if (!Number.isFinite(x)) return "—";
  return `${fmtNum(x)} ms`;
}

function esc(v) {
  return String(v ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function short(v, max = 62) {
  const t = String(v ?? "");
  return t.length > max ? `${t.slice(0, max - 1)}...` : t;
}

function fmtFechaHoraCorta(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  return `${d.toLocaleDateString("es-AR", { day: "2-digit", month: "2-digit" })} ${d.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false })}`;
}

function fmtFechaHoraLarga(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  return `${d.toLocaleDateString("es-AR", { day: "2-digit", month: "2-digit", year: "numeric" })} ${d.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false })}`;
}

function rv(str) {
  try {
    if (context?.grafana?.replaceVariables) {
      return context.grafana.replaceVariables(str);
    }
  } catch (e) { }
  return str;
}

function cleanValue(v) {
  const x = String(v ?? "").trim();
  if (!x) return null;
  if (x === "-1") return null;
  if (x.toUpperCase() === "ALL") return null;
  if (x.toUpperCase() === "TODAS LAS MARCAS") return null;
  return x;
}

function prettyMarca(v) {
  const x = String(v ?? "").toUpperCase();
  const map = {
    VISA: "Visa",
    MASTERCARD: "Mastercard",
    AMEX: "Amex",
    CABAL: "Cabal / Discover",
    CABAL_DISCOVER: "Cabal / Discover",
    DISCOVER: "Cabal / Discover",
    UPI: "UPI",
    OTRAS: "Otras",
    OTRA: "Otras",
    GENERAL: "General"
  };
  return map[x] || String(v ?? "General");
}

function emptyState(msg) {
  return {
    backgroundColor: bg,
    graphic: [
      {
        type: "text",
        left: 14,
        top: 8,
        style: {
          text: "Salud por marca",
          fill: aqua,
          font: "900 15px sans-serif"
        },
        silent: true
      },
      {
        type: "text",
        left: "center",
        top: "middle",
        style: {
          text: msg,
          fill: textSec,
          font: "800 13px sans-serif",
          textAlign: "center"
        },
        silent: true
      }
    ],
    xAxis: { show: false },
    yAxis: { show: false },
    series: [],
    animation: false
  };
}

if (!s || !s.fields || s.fields.length === 0) {
  return emptyState("Sin datos por marca");
}

// ---------- CAMPOS ----------
const marcasRaw = fieldAny(["marca", "brand", "marca_tx"]);
const totalTxRaw = fieldAny(["total_tx", "total", "tx", "total_transacciones"]);
const aprobadasRaw = fieldAny(["aprobadas", "tx_aprobadas"]);
const denegadasRaw = fieldAny(["denegadas", "rechazos", "tx_denegadas"]);
const reversosRaw = fieldAny(["reversos", "tx_reversos"]);
const p95Raw = fieldAny(["p95_ms", "latencia_ms", "latencia_p95_ms"]);
const tasaRaw = fieldAny(["tasa_aceptacion_pct", "tasa_aprobacion_pct", "disponibilidad_pct", "aceptacion_pct"]);
const tasaDenRaw = fieldAny(["tasa_denegacion_pct", "tasa_rechazo_pct"]);
const desdeRaw = fieldAny(["desde", "rango_desde"]);
const hastaRaw = fieldAny(["hasta", "rango_hasta"]);
const cuitRaw = firstAny(["cuit"], "-1");

if (!totalTxRaw.length) {
  return emptyState("Sin transacciones por marca");
}

// ---------- CLIENTE ----------
const selectedClienteRaw =
  cleanValue(rv("${cuit:raw}")) ||
  cleanValue(rv("${cuit:label}"));

let cliente = GLOBAL_CLIENTE;

if (selectedClienteRaw) {
  const c = String(selectedClienteRaw).replace(/[^0-9]/g, "");
  if (CLIENTES[c]) {
    cliente = CLIENTES[c];
  } else if (c && c !== "1" && c !== "-1") {
    cliente = { nombre: `CUIT ${c}`, color: textSoft };
  }
} else {
  const c = String(cuitRaw ?? "-1").replace(/[^0-9]/g, "");
  if (c && c !== "1" && c !== "-1") {
    cliente = CLIENTES[c] || { nombre: `CUIT ${c}`, color: textSoft };
  }
}

const selectedEst = cleanValue(rv("${establecimiento:raw}"));
const selectedMarcaRaw = cleanValue(rv("${marca:raw}"));
const selectedMarca = selectedMarcaRaw ? prettyMarca(selectedMarcaRaw) : null;

// ---------- DATA ----------
let rows = [];

for (let i = 0; i < totalTxRaw.length; i++) {
  const marca = prettyMarca(marcasRaw[i] ?? "General");
  const totalTx = num(totalTxRaw[i], 0);
  const tasa = tasaRaw.length ? num(tasaRaw[i], 0) : 0;

  if (!marca || totalTx <= 0) continue;

  rows.push({
    marca,
    totalTx,
    aprobadas: num(aprobadasRaw[i], 0),
    denegadas: num(denegadasRaw[i], 0),
    reversos: num(reversosRaw[i], 0),
    p95: num(p95Raw[i], null),
    tasa,
    tasaDen: tasaDenRaw.length ? num(tasaDenRaw[i], Math.max(0, 100 - tasa)) : Math.max(0, 100 - tasa),
    desde: desdeRaw[i],
    hasta: hastaRaw[i],
    brandColor: BRAND_COLORS[marca] || slate
  });
}

rows.sort((a, b) => b.totalTx - a.totalTx);

if (!rows.length) {
  return emptyState("Sin transacciones por marca");
}

const totalTxGlobal = rows.reduce((a, r) => a + r.totalTx, 0);
const totalDenGlobal = rows.reduce((a, r) => a + r.denegadas, 0);
const first = rows[0];

const rangoTxt =
  first?.desde && first?.hasta
    ? `${fmtFechaHoraCorta(first.desde)} - ${fmtFechaHoraCorta(first.hasta)}`
    : "rango seleccionado";

const rangoTooltip =
  first?.desde && first?.hasta
    ? `${fmtFechaHoraLarga(first.desde)} - ${fmtFechaHoraLarga(first.hasta)}`
    : "rango seleccionado";

const filtroTxt = [
  cliente.nombre,
  selectedEst ? `Est. ${selectedEst}` : "Todos los est.",
  selectedMarca || "Todas las marcas"
].join(" · ");

// ---------- LAYOUT FULL PANEL ----------
const W = context?.width || 900;
const H = context?.height || 230;

const graphics = [];
const rowMeta = [];

const leftPad = 16;
const rightPad = 16;

const isTiny = W < 520;
const titleFont = isTiny ? 12.5 : 15;
const subFont = isTiny ? 8 : 10.5;

const topHeader = 8;
const subHeader = 28;
const filterHeader = 45;
const listTop = 82;

const rowGap = 5;
const availableRowsH = Math.max(90, H - listTop - 12);

const rowH = Math.max(
  20,
  Math.min(38, (availableRowsH - rowGap * (rows.length - 1)) / rows.length)
);

const contentW = W - leftPad - rightPad;

const colMarca = leftPad + contentW * 0.03;
const colTasa = leftPad + contentW * 0.15;
const colTx = leftPad + contentW * 0.25;
const colRech = leftPad + contentW * 0.35;
const colP95 = leftPad + contentW * 0.45;

const showRech = W >= 430;
const showP95 = W >= 560;

const brandFont = Math.max(9, Math.min(12.5, rowH * 0.34));
const shareFont = Math.max(7, Math.min(9.5, rowH * 0.25));
const pctFont = Math.max(15, Math.min(22, rowH * 0.55));
const mainFont = Math.max(8.4, Math.min(11.5, rowH * 0.30));
const secFont = Math.max(7, Math.min(9.4, rowH * 0.24));

// HEADER
graphics.push({
  type: "text",
  left: leftPad,
  top: topHeader,
  style: {
    text: "Salud por marca",
    fill: aqua,
    font: `800 ${titleFont}px sans-serif`
  },
  silent: true
});

graphics.push({
  type: "text",
  left: leftPad,
  top: subHeader,
  style: {
    text: `${fmtShort(totalTxGlobal)} tx · ${rows.length} marcas · ${fmtShort(totalDenGlobal)} denegadas`,
    fill: textSec,
    font: `700 ${subFont}px sans-serif`,
    width: W * 0.55,
    overflow: "truncate"
  },
  silent: true
});

graphics.push({
  type: "text",
  right: rightPad,
  top: topHeader,
  style: {
    text: short(rangoTxt, W < 520 ? 18 : 34),
    fill: textSec,
    font: `700 ${isTiny ? 7.5 : subFont}px sans-serif`,
    textAlign: "right",
    width: W * 0.42,
    overflow: "truncate"
  },
  silent: true
});

// Filtro en línea propia para evitar solape
graphics.push({
  type: "text",
  left: leftPad,
  top: filterHeader,
  style: {
    text: short(filtroTxt, W < 520 ? 46 : W < 760 ? 70 : 100),
    fill: cliente.color,
    font: `900 ${isTiny ? 7.5 : 9}px sans-serif`,
    textAlign: "left",
    width: W - leftPad - rightPad,
    overflow: "truncate"
  },
  silent: true
});

// FILAS
rows.forEach((r, i) => {
  const y = listTop + i * (rowH + rowGap);
  const txShare = totalTxGlobal > 0 ? (r.totalTx * 100) / totalTxGlobal : 0;

  const yMain = y + rowH * 0.18;
  const ySub = y + rowH * 0.60;

  graphics.push({
    type: "rect",
    left: leftPad,
    top: y,
    shape: {
      width: colP95 + 75 - leftPad,
      height: rowH,
      r: 9
    },
    style: {
      fill: rowBg,
      stroke: border,
      lineWidth: 0
    },
    silent: true
  });

  graphics.push({
    type: "rect",
    left: leftPad,
    top: y,
    shape: {
      width: 5,
      height: rowH,
      r: [9, 0, 0, 9]
    },
    style: {
      fill: r.brandColor
    },
    silent: true
  });

  graphics.push({
    type: "text",
    left: colMarca,
    top: yMain,
    style: {
      text: short(r.marca, W < 520 ? 10 : 18),
      fill: r.brandColor,
      font: `900 ${brandFont}px sans-serif`
    },
    silent: true
  });

  graphics.push({
    type: "text",
    left: colMarca,
    top: ySub,
    style: {
      text: `${txShare.toFixed(1)}% tx`,
      fill: textSec,
      font: `700 ${shareFont}px sans-serif`
    },
    silent: true
  });

  graphics.push({
    type: "text",
    left: colTasa,
    top: yMain - 2,
    style: {
      text: fmtPct(r.tasa),
      fill: aqua,
      font: `900 ${pctFont}px sans-serif`
    },
    silent: true
  });

  graphics.push({
    type: "text",
    left: colTx,
    top: yMain,
    style: {
      text: `${fmtShort(r.totalTx)} tx`,
      fill: text,
      font: `900 ${mainFont}px sans-serif`
    },
    silent: true
  });

  graphics.push({
    type: "text",
    left: colTx,
    top: ySub,
    style: {
      text: `${fmtShort(r.aprobadas)} aprob.`,
      fill: textSec,
      font: `700 ${secFont}px sans-serif`
    },
    silent: true
  });

  if (showRech) {
    graphics.push({
      type: "text",
      left: colRech,
      top: yMain,
      style: {
        text: `${fmtPct(r.tasaDen)} rech.`,
        fill: coral,
        font: `900 ${mainFont}px sans-serif`
      },
      silent: true
    });

    graphics.push({
      type: "text",
      left: colRech,
      top: ySub,
      style: {
        text: fmtShort(r.denegadas),
        fill: textSec,
        font: `700 ${secFont}px sans-serif`
      },
      silent: true
    });
  }

  if (showP95) {
    graphics.push({
      type: "text",
      left: colP95,
      top: yMain,
      style: {
        text: `p95 ${fmtShort(r.p95)} ms`,
        fill: textSec,
        font: `900 ${mainFont}px sans-serif`
      },
      silent: true
    });

    graphics.push({
      type: "text",
      left: colP95,
      top: ySub,
      style: {
        text: `rev. ${fmtShort(r.reversos)}`,
        fill: textSec,
        font: `700 ${secFont}px sans-serif`
      },
      silent: true
    });
  }

  rowMeta.push({
    idx: i,
    x: leftPad,
    y,
    w: contentW,
    h: rowH,
    cx: leftPad + contentW / 2,
    cy: y + rowH / 2,
    row: r
  });
});

function tooltipFormatter(params) {
  const i = Array.isArray(params?.data) ? params.data[2] : params?.dataIndex ?? 0;
  const meta = rowMeta[i];
  const r = meta?.row || rows[0];

  if (!r) return "";

  const txShare = totalTxGlobal > 0 ? (r.totalTx * 100) / totalTxGlobal : 0;

  return `
    <div style="min-width:285px;max-width:430px;line-height:1.45">
      <div style="font-weight:900;color:${r.brandColor};margin-bottom:4px;font-size:13px">
        ${esc(r.marca)} · ${fmtPct(r.tasa)}
      </div>

      <div style="color:${cliente.color};font-weight:800;font-size:11px;margin-bottom:3px">
        ${esc(cliente.nombre)}
      </div>

      <div style="color:${textSec};font-size:10.5px;margin-bottom:8px">
        ${esc(selectedEst ? `Est. ${selectedEst}` : "Todos los est.")} · ${esc(selectedMarca || "Todas las marcas")}<br/>
        ${esc(rangoTooltip)}
      </div>

      <div style="border-top:1px solid rgba(148,163,184,0.18);padding-top:8px;color:${textSec};font-size:11px">
        Peso TX: <b style="color:${text}">${txShare.toFixed(1)}%</b><br/>
        Total TX: <b style="color:${text}">${fmtNum(r.totalTx)}</b><br/>
        Aprobadas: <b style="color:${aqua}">${fmtNum(r.aprobadas)}</b><br/>
        Denegadas: <b style="color:${coral}">${fmtNum(r.denegadas)}</b>
        <span style="color:${textSec}">(${fmtPct(r.tasaDen)})</span><br/>
        Reversos: <b style="color:${violet}">${fmtNum(r.reversos)}</b><br/>
        P95: <b style="color:${amber}">${fmtMs(r.p95)}</b>
      </div>
    </div>
  `;
}

const scatterData = rowMeta.map((m, i) => [m.cx, m.cy, i]);

return {
  backgroundColor: bg,

  tooltip: {
    trigger: "item",
    appendToBody: true,
    confine: true,
    enterable: false,
    backgroundColor: "rgba(8,13,24,0.96)",
    borderColor: aqua,
    borderWidth: 1,
    padding: 10,
    textStyle: {
      color: text,
      fontSize: 11,
      fontFamily: "Inter, Roboto, sans-serif"
    },
    formatter: tooltipFormatter
  },

  xAxis: {
    type: "value",
    min: 0,
    max: W,
    show: false
  },

  yAxis: {
    type: "value",
    min: 0,
    max: H,
    inverse: true,
    show: false
  },

  grid: {
    left: 0,
    right: 0,
    top: 0,
    bottom: 0
  },

  graphic: graphics,

  series: [
    {
      type: "scatter",
      coordinateSystem: "cartesian2d",
      data: scatterData,
      symbol: "rect",
      symbolSize: val => {
        const meta = rowMeta[val[2]];
        return meta ? [meta.w, meta.h] : [120, 34];
      },
      itemStyle: {
        color: "rgba(0,0,0,0)"
      },
      emphasis: {
        itemStyle: {
          color: "rgba(0,0,0,0)"
        }
      },
      silent: false
    }
  ],

  animation: false
};

