const GLOBAL_CLIENTE = {
  nombre: "PAYWAY GENERAL",
  color: textSec
};

// ---------- DATA ----------
const series = context.panel?.data?.series || [];
const s = series[0];

// ---------- HELPERS ----------
function valuesOfField(f) {
  if (!f) return [];
  if (typeof f.values?.toArray === "function") return f.values.toArray();
  return Array.from(f.values || []);
}

function fieldAny(names) {
  if (!s || !s.fields) return [];
  for (const name of names) {
    const f = s.fields.find(x =>
      String(x.name).toLowerCase() === String(name).toLowerCase()
    );
    const vals = valuesOfField(f);
    if (vals.length) return vals;
  }
  return [];
}

function allFieldNames() {
  if (!s || !s.fields) return "";
  return s.fields.map(f => f.name).join(", ");
}

function num(v, d = 0) {
  const x = Number(v);
  return Number.isFinite(x) ? x : d;
}

function fmtNum(v) {
  return num(v).toLocaleString("es-AR");
}

function fmtPct(v) {
  return `${num(v).toFixed(2)}%`;
}

function fmtPct1(v) {
  return `${num(v).toFixed(1)}%`;
}

function fmtHora(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  return d.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false });
}

function fmtDiaHora(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  return d.toLocaleDateString("es-AR", { day: "2-digit", month: "2-digit" }) + " " +
    d.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false });
}

function fmtFechaHora(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  const fecha = d.toLocaleDateString("es-AR", { day: "2-digit", month: "2-digit", year: "numeric" });
  const hora = d.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false });
  return `${fecha} ${hora}`;
}

function fmtFechaHoraCorta(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  const fecha = d.toLocaleDateString("es-AR", { day: "2-digit", month: "2-digit" });
  const hora = d.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false });
  return `${fecha} ${hora}`;
}

function esc(v) {
  return String(v ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function rv(str) {
  try {
    if (context?.grafana?.replaceVariables) {
      return context.grafana.replaceVariables(str);
    }
  } catch (e) { }
  return str;
}

function cleanValue(v) {
  const x = String(v ?? "").trim();
  if (!x) return null;
  if (x === "-1") return null;
  if (x.toUpperCase() === "ALL") return null;
  if (x.toUpperCase() === "TODAS LAS MARCAS") return null;
  return x;
}

function prettyMarca(v) {
  const x = String(v ?? "-").toUpperCase();
  const map = {
    VISA: "Visa", MASTERCARD: "Mastercard", AMEX: "Amex",
    CABAL_DISCOVER: "Cabal / Discover", UPI: "UPI", OTRAS: "Otras", "-": "-"
  };
  return map[x] || v;
}

function prettyCodigo(v) {
  const x = String(v ?? "-").trim();
  if (!x || x === "-") return "-";
  if (x === "SIN_DESC") return "Sin catalogo";
  if (x === "SIN_CODIGO") return "S/C";
  return x;
}

function normalizeQuadrant(v) {
  const raw = String(v ?? "").trim();
  const upper = raw.toUpperCase();
  if (!raw) return null;
  if (COLORS_CUADRANTE[raw]) return raw;
  if (upper === "RIESGO EMISOR") return "Riesgo Emisor";
  if (upper === "OPERATIVO EMISOR") return "Operativo Emisor";
  if (upper === "RIESGO ADQUIRENTE") return "Riesgo Adquirente";
  if (upper === "OPERATIVO ADQUIRENTE") return "Operativo Adquirente";
  if (upper === "EMISOR NO CATALOGADO") return "Emisor no catalogado";
  if (upper === "CODIGO EMISOR DE OTRAS MARCAS") return "Emisor no catalogado";
  if (upper === "CODIGO EMISOR - MARCA NO MAPEADA") return "Emisor no catalogado";
  if (upper === "ISSUER NO MAPEADO") return "Emisor no catalogado";
  if (upper === "EMISOR NO MAPEADO") return "Emisor no catalogado";
  if (upper === "OTROS") return "Otros";
  return raw;
}

function bullet(color) {
  return `<span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:${color};margin-right:6px;"></span>`;
}

function short(v, max = 70) {
  const t = String(v ?? "");
  return t.length > max ? `${t.slice(0, max - 1)}...` : t;
}

// ---------- EMPTY ----------
if (!s || !s.fields || s.fields.length === 0) {
  return {
    backgroundColor: bg,
    graphic: [{
      type: "text", left: "center", top: "middle",
      style: { text: "Sin datos", fill: textSec, font: "600 12px sans-serif" }
    }],
    xAxis: { show: false }, yAxis: { show: false }, series: [], animation: false
  };
}

// ---------- CAMPOS ----------
const tiemposRaw = fieldAny(["time", "bucket_utc", "minuto_utc", "timestamp"]);
const tasaRaw = fieldAny(["tasa_actual"]);
const historicoRaw = fieldAny(["historico", "promedio_historico", "mediana"]);
const totalTxRaw = fieldAny(["total_tx"]);
const aprobadasRaw = fieldAny(["aprobadas"]);
const denegadasRaw = fieldAny(["denegadas"]);
const reversosRaw = fieldAny(["reversos"]);
const cambioRaw = fieldAny(["cambio_significativo"]);
const zScoreRaw = fieldAny(["z_score_robusto", "zscore_robusto"]);
const cuitRaw = fieldAny(["cuit"]);
const desdeRaw = fieldAny(["rango_desde", "desde"]);
const hastaRaw = fieldAny(["rango_hasta", "hasta"]);
const establecimientoRaw = fieldAny(["establecimiento", "nro_establecimiento"]);
const marcaRaw = fieldAny(["marca"]);

const cuadranteDomRaw = fieldAny(["cuadrante_dominante"]);
const codigoDomRaw = fieldAny(["codigo_dominante"]);
const marcaDomRaw = fieldAny(["marca_dominante"]);
const origenDomRaw = fieldAny(["origen_codigo_dominante"]);
const tipoDomRaw = fieldAny(["tipo_codigo_dominante"]);
const rechCodigoDomRaw = fieldAny(["rechazos_codigo_dominante"]);
const pctCodigoDomRaw = fieldAny(["pct_codigo_dominante"]);

if (!tiemposRaw.length || !tasaRaw.length) {
  return {
    backgroundColor: bg,
    title: {
      text: "Tasa de aceptacion", subtext: "Faltan campos esperados",
      left: 12, top: 8,
      textStyle: { color: text, fontSize: 12, fontWeight: 800 },
      subtextStyle: { color: textSec, fontSize: 10 }
    },
    graphic: [{
      type: "text", left: "center", top: "middle",
      style: {
        text: "Esperados: time, tasa_actual\n\nRecibidos:\n" + allFieldNames(),
        fill: textSec, font: "600 11px sans-serif", width: 420, overflow: "break", textAlign: "center"
      }
    }],
    xAxis: { show: false }, yAxis: { show: false }, series: [], animation: false
  };
}

// ---------- ARRAYS (let: se reasignan si hay agregacion) ----------
let tiempos = [];
let tasa = [];
let historico = [];
let totalTx = [];
let aprobadas = [];
let denegadas = [];
let reversos = [];
let cambio = [];
let zScore = [];
let detalleDominante = [];

for (let i = 0; i < tiemposRaw.length; i++) {
  const t = tiemposRaw[i];
  const d = new Date(t);
  const timeValue = !isNaN(d.getTime()) ? d.toISOString() : String(t);

  tiempos.push(timeValue);
  tasa.push(tasaRaw[i] == null ? null : num(tasaRaw[i], null));
  historico.push(historicoRaw[i] == null ? null : num(historicoRaw[i], null));
  totalTx.push(num(totalTxRaw[i], 0));
  aprobadas.push(num(aprobadasRaw[i], 0));
  denegadas.push(num(denegadasRaw[i], 0));
  reversos.push(num(reversosRaw[i], 0));
  cambio.push(num(cambioRaw[i], 0));
  zScore.push(zScoreRaw[i] == null ? null : num(zScoreRaw[i], null));

  detalleDominante.push({
    cuadrante: normalizeQuadrant(cuadranteDomRaw[i]),
    codigo: prettyCodigo(codigoDomRaw[i]),
    marca: prettyMarca(marcaDomRaw[i]),
    origen: String(origenDomRaw[i] ?? "-"),
    tipo: String(tipoDomRaw[i] ?? "-"),
    rechazosCodigo: num(rechCodigoDomRaw[i], 0),
    pctCodigo: num(pctCodigoDomRaw[i], 0)
  });
}

// ======================================================================================
// v2 · AGREGACION ADAPTATIVA
// Con rangos largos (p.ej. 7d = 10.080 minutos) las lineas por minuto se amontonan.
// Si hay mas de MAX_PTS puntos, se agrupan k minutos por bucket recalculando las
// metricas de forma consistente (tasa ponderada por tx, historico promediado).
// ======================================================================================
const MAX_PTS = 720;          // techo de puntos en pantalla
const MIN_PTS = 30;           // piso de puntos (no agregar de mas)
const TX_POR_BUCKET = 60;     // volumen minimo por bucket para tasa estable
let kAgg = Math.ceil(tiempos.length / MAX_PTS);
{
  const txTot = totalTx.reduce((a, b) => a + b, 0);
  const avgMin = txTot / Math.max(tiempos.length, 1);
  if (avgMin > 0 && avgMin < TX_POR_BUCKET) {
    kAgg = Math.max(kAgg, Math.ceil(TX_POR_BUCKET / avgMin));
  }
  kAgg = Math.max(1, Math.min(kAgg, Math.max(1, Math.floor(tiempos.length / MIN_PTS))));
}
if (kAgg > 1) {
  const k = kAgg;
  const T = [], TA = [], H = [], TT = [], AP = [], DE = [], RV = [], CB = [], ZS = [], DD = [];
  for (let i = 0; i < tiempos.length; i += k) {
    const j = Math.min(i + k, tiempos.length);
    let tt = 0, ap = 0, de = 0, rvs = 0, hs = 0, hn = 0, cb = 0, zb = null, dd = null, ddMax = -1;
    for (let q = i; q < j; q++) {
      tt += totalTx[q]; ap += aprobadas[q]; de += denegadas[q]; rvs += reversos[q];
      if (historico[q] != null) { hs += historico[q]; hn++; }
      if (cambio[q] === 1) { cb = 1; if (zScore[q] != null) zb = zScore[q]; }
      const dq = detalleDominante[q];
      if (dq && num(dq.rechazosCodigo, 0) > ddMax) { ddMax = num(dq.rechazosCodigo, 0); dd = dq; }
    }
    T.push(tiempos[i]);
    TA.push(tt > 0 ? Math.round(10000 * ap / tt) / 100 : null);
    H.push(hn ? Math.round(100 * hs / hn) / 100 : null);
    TT.push(tt); AP.push(ap); DE.push(de); RV.push(rvs);
    CB.push(cb); ZS.push(zb); DD.push(dd || {});
  }
  tiempos = T; tasa = TA; historico = H; totalTx = TT; aprobadas = AP;
  denegadas = DE; reversos = RV; cambio = CB; zScore = ZS; detalleDominante = DD;
}

const nPts = tiempos.length;
const pocosPuntos = nPts <= 220;                 // zoom corto: mostrar simbolos
const bucketMin = Math.max(1, Math.ceil(tiemposRaw.length / Math.max(nPts, 1)));

// ---------- CLIENTE / FILTROS ----------
const cuitValues = cuitRaw.filter(v => v != null).map(v => String(v).replace(/[^0-9]/g, ""));
const uniqueCuits = [...new Set(cuitValues)];
let cliente = GLOBAL_CLIENTE;

const selectedCliente = cleanValue(rv("${cuit:label}")) || cleanValue(rv("${cuit:raw}"));

if (selectedCliente) {
  const c = String(selectedCliente).replace(/[^0-9]/g, "");
  if (CLIENTES[c]) cliente = CLIENTES[c];
  else if (c && c !== "1" && c !== "-1") cliente = { nombre: `CUIT ${c}`, color: textSec };
  else cliente = GLOBAL_CLIENTE;
} else if (uniqueCuits.length === 1 && uniqueCuits[0] && uniqueCuits[0] !== "1" && uniqueCuits[0] !== "-1") {
  const c = uniqueCuits[0];
  cliente = CLIENTES[c] || { nombre: `CUIT ${c}`, color: textSec };
}

const selectedEst = cleanValue(rv("${establecimiento:raw}")) || cleanValue(String(establecimientoRaw[0] ?? ""));
const selectedMarcaRaw = cleanValue(rv("${marca:raw}")) || cleanValue(String(marcaRaw[0] ?? ""));
const selectedMarca = selectedMarcaRaw ? prettyMarca(selectedMarcaRaw) : null;

const filtroTxt = [
  cliente.nombre,
  selectedEst ? `Est. ${selectedEst}` : "Todos los est.",
  selectedMarca || "Todas las marcas"
].join(" · ");

// ---------- RANGO ----------
const rangoDesde = desdeRaw.length ? desdeRaw[0] : tiempos[0];
const rangoHasta = hastaRaw.length ? hastaRaw[0] : tiempos[tiempos.length - 1];

const rangoTxt = rangoDesde && rangoHasta
  ? `${fmtFechaHoraCorta(rangoDesde)} - ${fmtFechaHoraCorta(rangoHasta)}`
  : "rango seleccionado";

const rangoTooltip = rangoDesde && rangoHasta
  ? `${fmtFechaHora(rangoDesde)} - ${fmtFechaHora(rangoHasta)}`
  : "rango seleccionado";

// rango temporal en ms para decidir formato del eje X
const spanMs = (() => {
  const a = new Date(tiempos[0]).getTime();
  const b = new Date(tiempos[tiempos.length - 1]).getTime();
  return (Number.isFinite(a) && Number.isFinite(b)) ? (b - a) : 0;
})();
const ejeConFecha = spanMs > 36 * 3600 * 1000;

// ======================================================================================
// v2 · ESCALA ADAPTATIVA DEL EJE IZQUIERDO
// En vez de 0-100 fijo (que aplasta la linea en una banda finita), el eje se ajusta
// a la banda real de la tasa + historico con un margen. Asi el deep dive es legible.
// ======================================================================================
const bandVals = [];
for (const v of tasa) if (v != null && Number.isFinite(v)) bandVals.push(v);
for (const v of historico) if (v != null && Number.isFinite(v)) bandVals.push(v);

let yMinL = 0, yMaxL = 100;
if (bandVals.length) {
  let mn = bandVals[0], mx = bandVals[0];
  for (const v of bandVals) { if (v < mn) mn = v; if (v > mx) mx = v; }
  const pad = Math.max((mx - mn) * 0.25, 1.5);
  yMinL = Math.max(0, Math.floor(mn - pad));
  yMaxL = Math.min(100, Math.ceil(mx + pad));
  if (yMaxL - yMinL < 4) {                      // banda minima para que no sea plano
    yMinL = Math.max(0, yMinL - 2);
    yMaxL = Math.min(100, yMaxL + 2);
  }
}

// ---------- PUNTOS SEMANTICOS ----------
const tasaConPuntos = tasa.map((v, i) => {
  if (v == null) return [tiempos[i], null];
  if (cambio[i] === 1) {
    const hist = historico[i];
    const esPositivo = hist == null ? false : v >= hist;
    return {
      value: [tiempos[i], v],
      symbol: "circle",
      symbolSize: 9,
      itemStyle: {
        color: esPositivo ? palette.positivo : palette.negativo,
        borderColor: bg, borderWidth: 1.5
      }
    };
  }
  return [tiempos[i], v];
});

const historicoSeries = tiempos.map((t, i) => [t, historico[i]]);
const totalTxSeries = tiempos.map((t, i) => [t, totalTx[i]]);
const reversosSeries = tiempos.map((t, i) => [t, reversos[i]]);

let maxTx = 1, maxRev = 1;
for (const v of totalTx) if (v > maxTx) maxTx = v;
for (const v of reversos) if (v > maxRev) maxRev = v;
const maxRight = Math.max(maxTx, maxRev, 1);

// ---------- TOOLTIP ----------
function tooltipFormatter(params) {
  const arr = Array.isArray(params) ? params : [params];
  if (!arr.length) return "";

  const idx = arr[0]?.dataIndex ?? 0;
  const t = tiempos[idx];

  const ta = tasa[idx];
  const hist = historico[idx];
  const tx = totalTx[idx];
  const apr = aprobadas[idx];
  const den = denegadas[idx];
  const rev = reversos[idx];
  const z = zScore[idx];

  const dom = detalleDominante[idx] || {};
  const cuadrante = dom.cuadrante;
  const qColor = COLORS_CUADRANTE[cuadrante] || slate;

  const tieneDominante =
    cuadrante && dom.codigo && dom.codigo !== "-" && dom.codigo !== "S/C" &&
    num(dom.rechazosCodigo, 0) > 0;

  const diferencia = (ta != null && hist != null) ? ta - hist : null;

  let out = `
    <div style="min-width:315px;max-width:460px">
      <div style="font-weight:800;color:${text};margin-bottom:5px">
        ${fmtFechaHora(t)}${bucketMin > 1 ? ` <span style="color:${textSec};font-weight:400;font-size:10px">(bucket ${bucketMin} min)</span>` : ""}
      </div>
      <div style="color:${textSec};font-size:10.5px;margin-bottom:8px;line-height:1.4">
        ${esc(short(filtroTxt, 82))}<br/>
        ${esc(rangoTooltip)}
      </div>
      <div style="color:${textSec};font-size:11px;line-height:1.55">
        <div>${bullet(palette.tasa)}Tasa actual:
          <b style="color:${text}">${ta == null ? "—" : fmtPct(ta)}</b>
        </div>
        <div>${bullet(palette.historico)}Historico:
          <b style="color:${text}">${hist == null ? "—" : fmtPct(hist)}</b>
        </div>
        <div>${bullet(palette.tx)}Transacciones:
          <b style="color:${text}">${fmtNum(tx)}</b>
          <span style="color:${textSec}">(${fmtNum(apr)} aprobadas / ${fmtNum(den)} denegadas)</span>
        </div>
        <div>${bullet(palette.reversos)}Reversos:
          <b style="color:${text}">${fmtNum(rev)}</b>
        </div>
      </div>
  `;

  if (z != null || cambio[idx] === 1 || diferencia != null) {
    const esPositivo = diferencia != null ? diferencia >= 0 : false;
    const colorCambio = esPositivo ? palette.positivo : palette.negativo;
    out += `
      <div style="border-top:1px solid rgba(148,163,184,0.16);margin-top:8px;padding-top:7px;color:${textSec};font-size:11px;line-height:1.45;">
        Diferencia vs historico:
        <b style="color:${colorCambio}">
          ${diferencia == null ? "—" : `${diferencia >= 0 ? "+" : ""}${diferencia.toFixed(2)} pp`}
        </b><br/>
        Z-score robusto:
        <b style="color:${cambio[idx] === 1 ? colorCambio : text}">
          ${z == null ? "—" : z.toFixed(2)}
        </b>
        ${cambio[idx] === 1
        ? `<br/><b style="color:${colorCambio}">${esPositivo ? "Comportamiento mejor que lo habitual" : "Comportamiento por debajo de lo habitual"}</b>`
        : ""}
      </div>
    `;
  }

  if (tieneDominante) {
    out += `
      <div style="border-top:1px solid rgba(148,163,184,0.16);margin-top:8px;padding-top:7px;color:${textSec};font-size:11px;line-height:1.45;">
        <div style="font-weight:800;color:${qColor};margin-bottom:3px">${esc(cuadrante)}</div>
        Dominante:
        <b style="color:${textSoft}">${esc(dom.codigo)}</b>
        <span style="color:${textSec}"> · ${esc(dom.marca)}</span>
        ${num(dom.pctCodigo, 0) > 0 ? `<span style="color:${textSec}"> · ${fmtPct1(dom.pctCodigo)}</span>` : ""}
        ${num(dom.rechazosCodigo, 0) > 0 ? `<span style="color:${textSec}"> · ${fmtNum(dom.rechazosCodigo)} rech.</span>` : ""}
        <br/>
        <span style="color:${textSec}">${esc(dom.origen)} / ${esc(dom.tipo)}</span>
      </div>
    `;
  } else if (den > 0) {
    out += `
      <div style="border-top:1px solid rgba(148,163,184,0.16);margin-top:8px;padding-top:7px;color:${textSec};font-size:11px;line-height:1.45;">
        Codigo dominante: <b style="color:${textSoft}">sin dominante disponible</b>
      </div>
    `;
  }

  out += `</div>`;
  return out;
}

// ---------- GRAPHICS ----------
const graphics = [];

graphics.push({
  type: "text", left: 12, top: 8,
  style: { text: "Tasa de aceptacion", fill: aqua, font: "bold 13px sans-serif" },
  silent: true
});

graphics.push({
  type: "text", left: 12, top: 25,
  style: {
    text: `${rangoTxt} · ${bucketMin > 1 ? `serie cada ${bucketMin} min` : "serie por minuto"} · eje ${yMinL}-${yMaxL}%`,
    fill: textSec, font: "10px sans-serif"
  },
  silent: true
});

graphics.push({
  type: "text", right: 16, top: 8,
  style: { text: cliente.nombre, fill: cliente.color, font: "bold 10.5px sans-serif", textAlign: "right" },
  silent: true
});

graphics.push({
  type: "text", right: 16, top: 25,
  style: {
    text: short(`${selectedEst ? `Est. ${selectedEst}` : "Todos los est."} · ${selectedMarca || "Todas las marcas"}`, 70),
    fill: textSoft, font: "10px sans-serif", textAlign: "right"
  },
  silent: true
});

graphics.push({
  type: "text", left: "center", bottom: 8,
  style: { text: filtroTxt, fill: cliente.color, font: "bold 10px sans-serif", textAlign: "center" },
  silent: true
});

// ---------- RETURN ----------
return {
  backgroundColor: bg,

  color: [palette.tasa, palette.historico, palette.tx, palette.reversos],

  title: {
    text: "Actual vs historico",
    left: 12, top: 43,
    textStyle: { color: text, fontSize: 12, fontWeight: 800 }
  },

  legend: {
    top: 65, left: 12, itemWidth: 7, itemHeight: 7, icon: "circle", itemGap: 10,
    textStyle: { color: textSec, fontSize: 8.5 },
    data: ["Tasa actual", "Historico", "Transacciones", "Reversos"]
  },

  tooltip: {
    trigger: "axis",
    appendToBody: false, confine: true, enterable: false,
    backgroundColor: "rgba(11,15,24,0.78)",
    borderColor: "rgba(0,244,196,0.55)", borderWidth: 1, padding: 9,
    textStyle: { color: text, fontSize: 11, fontFamily: "Inter, Roboto, sans-serif" },
    axisPointer: { type: "line", lineStyle: { color: "rgba(255,255,255,0.22)", width: 1 } },
    position: function (point, params, dom, rect, size) {
      const boxW = size.contentSize[0] || 330;
      const boxH = size.contentSize[1] || 210;
      const viewW = size.viewSize[0] || 500;
      const viewH = size.viewSize[1] || 260;
      let left = point[0] + 24;
      let top = point[1] - boxH / 2;
      if (left + boxW > viewW - 8) left = point[0] - boxW - 14;
      if (left < 8) left = 8;
      if (top < 8) top = 8;
      if (top + boxH > viewH - 8) top = Math.max(8, viewH - boxH - 8);
      return [left, top];
    },
    formatter: tooltipFormatter
  },

  grid: { left: 44, right: 44, top: 96, bottom: 42 },

  xAxis: {
    type: "time",
    boundaryGap: false,
    axisLine: { lineStyle: { color: "rgba(148,163,184,0.16)" } },
    axisTick: { show: false },
    axisLabel: {
      color: textSec, fontSize: 8.5, margin: 10, hideOverlap: true,
      formatter: value => ejeConFecha ? fmtDiaHora(value) : fmtHora(value)
    },
    splitLine: { show: false }
  },

  yAxis: [
    {
      // v2: banda adaptativa en lugar de 0-100 fijo
      type: "value",
      min: yMinL,
      max: yMaxL,
      splitNumber: 5,
      axisLine: { show: false },
      axisTick: { show: false },
      axisLabel: { color: textSec, fontSize: 8.5, formatter: value => `${value}%` },
      splitLine: { lineStyle: { color: grid } }
    },
    {
      type: "value",
      min: 0,
      max: Math.max(10, Math.ceil(maxRight * 1.15)),
      axisLine: { show: false },
      axisTick: { show: false },
      axisLabel: { color: textSec, fontSize: 8.5, formatter: value => fmtNum(value) },
      splitLine: { show: false }
    }
  ],

  series: [
    {
      name: "Tasa actual",
      type: "line",
      yAxisIndex: 0,
      data: tasaConPuntos,
      smooth: pocosPuntos ? 0.15 : 0.32,
      symbol: pocosPuntos ? "circle" : "none",
      symbolSize: 5,
      connectNulls: true,
      lineStyle: { width: pocosPuntos ? 2.6 : 2.2, color: palette.tasa },
      itemStyle: { color: palette.tasa },
      areaStyle: { opacity: 0.14, color: palette.tasa },
      emphasis: { focus: "series" }
    },
    {
      name: "Historico",
      type: "line",
      yAxisIndex: 0,
      data: historicoSeries,
      smooth: pocosPuntos ? 0.15 : 0.32,
      symbol: "none",
      connectNulls: true,
      lineStyle: { width: 1.8, type: "dashed", color: palette.historico },
      itemStyle: { color: palette.historico },
      emphasis: { focus: "series" }
    },
    {
      name: "Transacciones",
      type: "line",
      yAxisIndex: 1,
      data: totalTxSeries,
      smooth: 0.25,
      symbol: pocosPuntos ? "circle" : "none",
      symbolSize: 4,
      connectNulls: true,
      lineStyle: { width: 1.6, color: palette.tx, opacity: 0.78 },
      itemStyle: { color: palette.tx },
      emphasis: { focus: "series" }
    },
    {
      name: "Reversos",
      type: "line",
      yAxisIndex: 1,
      data: reversosSeries,
      smooth: 0.25,
      symbol: pocosPuntos ? "circle" : "none",
      symbolSize: 4,
      connectNulls: true,
      lineStyle: { width: 1.5, type: "dotted", color: palette.reversos, opacity: 0.82 },
      itemStyle: { color: palette.reversos },
      emphasis: { focus: "series" }
    }
  ],

  graphic: graphics,
  animation: false
};

options.getOption:
const series = context.panel.data.series.map((s) => {
  const sData = s.fields.find((f) => f.type === 'number').values.buffer || s.fields.find((f) => f.type === 'number').values;
  const sTime = s.fields.find((f) => f.type === 'time').values.buffer || s.fields.find((f) => f.type === 'time').values;

  return {
