// ======================================================================================
// BUSINESS CHART — NIVEL DE ACTIVIDAD / TOTAL TX · ACTUAL VS MEDIANA HISTORICA
// v2 DEEP-DIVE FIX:
//   • Eje izquierdo ADAPTATIVO: se ajusta a la banda real de actividad (no 0-100 fijo)
//   • Agregacion automatica de buckets cuando hay >720 puntos (rangos largos legibles)
//   • Disponibilidad recalculada por bucket (tx agregadas / referencia agregada) —
//     elimina el efecto "onda cuadrada" del calculo por minuto
//   • Simbolos visibles cuando hay pocos puntos (zoom corto legible)
//   • connectNulls para que minutos sin trafico no corten la linea
//   • Fechas en el eje X cuando el rango supera 36h
// ======================================================================================

// ---------- PALETA ----------
const aqua = "#00F4C4";
const amber = "#E7B432";
const blue = "#3B82F6";
const red = "#EF4444";
const green = "#22C55E";
const violet = "#7C6AE6";

const bg = "#0a0e17";
const grid = "rgba(148,163,184,0.12)";
const text = "#E5E7EB";
const textSoft = "#CBD5E1";
const textSec = "#8b93a7";

const palette = {
  actividad: aqua,
  historico: amber,
  tx: blue,
  reversos: red,
  positivo: green,
  negativo: amber
};

// ---------- CUIT → CLIENTE ----------
const CLIENTES = {
  "30641405554": { nombre: "AEROLINEAS ARGENTINAS", color: green },
  "30503612891": { nombre: "BGH", color: green },
  "30663205621": { nombre: "CAJA DE SEGUROS", color: green },
  "30590360763": { nombre: "CENCOSUD", color: aqua },
  "30592845748": { nombre: "CETROGAR", color: amber },
  "30663288497": { nombre: "CLARO", color: blue },
  "30680743068": { nombre: "CLARO PAY", color: blue },
  "30525705931": { nombre: "COOPERATIVA OBRERA", color: aqua },
  "30548083156": { nombre: "COTO CICSA", color: aqua },
  "30638485733": { nombre: "DABRA SA", color: amber },
  "30718955722": { nombre: "DECATHLON", color: amber },
  "30516186670": { nombre: "DEHEZA SA", color: aqua },
  "30701307115": { nombre: "DESPEGAR", color: amber },
  "30711998612": { nombre: "DLP", color: amber },
  "30655116202": { nombre: "EDENOR", color: green },
  "30692138747": { nombre: "FARMACITY", color: aqua },
  "33707366589": { nombre: "FED. PATRONAL", color: green },
  "30526874249": { nombre: "FRAVEGA", color: amber },
  "30715621866": { nombre: "GMRA SA", color: amber },
  "30687310434": { nombre: "INC SA", color: amber },
  "30506730038": { nombre: "LA ANONIMA", color: aqua },
  "30703088534": { nombre: "MERCADO LIBRE", color: amber },
  "30532847547": { nombre: "MEGATONE", color: amber },
  "33707013139": { nombre: "MOSTAZA Y PAN", color: green },
  "30543659734": { nombre: "ON CITY", color: amber },
  "30711792186": { nombre: "PAGO VIRTUAL DEL SUR", color: violet },
  "30714407313": { nombre: "PAGOS360", color: violet },
  "30715221159": { nombre: "PAGOSYA", color: violet },
  "30695542476": { nombre: "PAN AMERICAN ENERGY", color: amber },
  "30708743514": { nombre: "PAYU", color: violet },
  "30707743987": { nombre: "PLUS PAGOS", color: violet },
  "30704950345": { nombre: "PROVINCIA NET", color: violet },
  "30659863789": { nombre: "SERV. ELECTRONICO DE PAGO", color: violet },
  "30612865333": { nombre: "VITAL", color: aqua },
  "30589621499": { nombre: "MAKRO", color: aqua },
  "30654855168": { nombre: "SWISS MEDICAL", color: green },
  "30640897267": { nombre: "TELECENTRO", color: blue },
  "30639453738": { nombre: "TELECOM", color: blue },
  "30678814357": { nombre: "MOVISTAR", color: blue },
  "33690765549": { nombre: "TICKETEK", color: green },
  "30715778722": { nombre: "TODOTRAIL", color: amber },
  "30716370964": { nombre: "VIUMI", color: amber },
  "30655534462": { nombre: "VISUAR", color: violet }
};

const GLOBAL_CLIENTE = {
  nombre: "PAYWAY GENERAL",
  color: textSec
};

// ---------- DATA ----------
const series = context.panel?.data?.series || [];
const s = series[0];

// ---------- HELPERS ----------
function valuesOfField(f) {
  if (!f) return [];
  if (typeof f.values?.toArray === "function") return f.values.toArray();
  return Array.from(f.values || []);
}

function fieldAny(names) {
  if (!s || !s.fields) return [];
  for (const name of names) {
    const f = s.fields.find(x =>
      String(x.name).toLowerCase() === String(name).toLowerCase()
    );
    const vals = valuesOfField(f);
    if (vals.length) return vals;
  }
  return [];
}

function allFieldNames() {
  if (!s || !s.fields) return "";
  return s.fields.map(f => f.name).join(", ");
}

function num(v, d = 0) {
  const x = Number(v);
  return Number.isFinite(x) ? x : d;
}

function nullableNum(v) {
  const x = Number(v);
  return Number.isFinite(x) ? x : null;
}

function fmtNum(v) {
  return num(v).toLocaleString("es-AR");
}

function fmtPct(v) {
  const x = Number(v);
  return Number.isFinite(x) ? `${x.toFixed(2)}%` : "—";
}

function fmtFechaHora(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  const fecha = d.toLocaleDateString("es-AR", { day: "2-digit", month: "2-digit", year: "numeric" });
  const hora = d.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false });
  return `${fecha} ${hora}`;
}

function fmtFechaHoraCorta(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  const fecha = d.toLocaleDateString("es-AR", { day: "2-digit", month: "2-digit" });
  const hora = d.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false });
  return `${fecha} ${hora}`;
}

function fmtHora(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  return d.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false });
}

function fmtDiaHora(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  return d.toLocaleDateString("es-AR", { day: "2-digit", month: "2-digit" }) + " " +
    d.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false });
}

function esc(v) {
  return String(v ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function bullet(color) {
  return `<span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:${color};margin-right:6px;"></span>`;
}

function rv(str) {
  try {
    if (context?.grafana?.replaceVariables) {
      return context.grafana.replaceVariables(str);
    }
  } catch (e) { }
  return str;
}

function cleanValue(v) {
  const x = String(v ?? "").trim();
  if (!x) return null;
  if (x === "-1") return null;
  if (x.toUpperCase() === "ALL") return null;
  if (x.toUpperCase() === "TODAS LAS MARCAS") return null;
  return x;
}

function prettyMarca(v) {
  const x = String(v ?? "-").toUpperCase();
  const map = {
    VISA: "Visa", MASTERCARD: "Mastercard", AMEX: "Amex",
    CABAL_DISCOVER: "Cabal / Discover", UPI: "UPI", OTRAS: "Otras", "-": "-"
  };
  return map[x] || v;
}

function short(v, max = 72) {
  const t = String(v ?? "");
  return t.length > max ? `${t.slice(0, max - 1)}...` : t;
}

// ---------- EMPTY ----------
if (!s || !s.fields || s.fields.length === 0) {
  return {
    backgroundColor: bg,
    graphic: [{
      type: "text", left: "center", top: "middle",
      style: { text: "Sin datos", fill: textSec, font: "600 12px sans-serif" }
    }],
    xAxis: { show: false }, yAxis: { show: false }, series: [], animation: false
  };
}

// ---------- CAMPOS ----------
const tiemposRaw = fieldAny(["time", "bucket_utc", "minuto_utc", "timestamp"]);
const actividadRaw = fieldAny(["disponibilidad_pct", "actividad_pct", "nivel_actividad_pct"]);
const historicoRaw = fieldAny(["referencia_historica", "historico", "mediana"]);
const totalTxRaw = fieldAny(["total_tx_actual", "total_tx"]);
const reversosRaw = fieldAny(["reversos"]);
const cambioRaw = fieldAny(["cambio_significativo"]);
const zScoreRaw = fieldAny(["z_score_robusto", "zscore_robusto"]);
const cuitRaw = fieldAny(["cuit"]);
const desdeRaw = fieldAny(["rango_desde", "desde"]);
const hastaRaw = fieldAny(["rango_hasta", "hasta"]);
const establecimientoRaw = fieldAny(["establecimiento", "nro_establecimiento"]);
const marcaRaw = fieldAny(["marca"]);

if (!tiemposRaw.length || !actividadRaw.length) {
  return {
    backgroundColor: bg,
    title: {
      text: "Nivel de actividad", subtext: "Faltan campos esperados",
      left: 12, top: 8,
      textStyle: { color: text, fontSize: 12, fontWeight: 800 },
      subtextStyle: { color: textSec, fontSize: 10 }
    },
    graphic: [{
      type: "text", left: "center", top: "middle",
      style: {
        text: "Esperados: time, disponibilidad_pct\n\nRecibidos:\n" + allFieldNames(),
        fill: textSec, font: "600 11px sans-serif", width: 420, overflow: "break", textAlign: "center"
      }
    }],
    xAxis: { show: false }, yAxis: { show: false }, series: [], animation: false
  };
}

// ---------- ARRAYS (let: se reasignan si hay agregacion) ----------
let tiempos = [];
let actividad = [];
let historico = [];
let totalTx = [];
let reversos = [];
let cambio = [];
let zScore = [];

for (let i = 0; i < tiemposRaw.length; i++) {
  const t = tiemposRaw[i];
  const d = new Date(t);
  const timeValue = !isNaN(d.getTime()) ? d.toISOString() : String(t);

  tiempos.push(timeValue);
  actividad.push(nullableNum(actividadRaw[i]));
  historico.push(nullableNum(historicoRaw[i]));
  totalTx.push(num(totalTxRaw[i], 0));
  reversos.push(num(reversosRaw[i], 0));
  cambio.push(num(cambioRaw[i], 0));
  zScore.push(nullableNum(zScoreRaw[i]));
}

// ======================================================================================
// v2 · AGREGACION ADAPTATIVA
// Con rangos largos (7d = 10.080 minutos) la serie por minuto se vuelve ruido.
// Si hay mas de MAX_PTS puntos, se agrupan k minutos por bucket y la disponibilidad
// se RECALCULA con los agregados: min(100, 100 * tx_bucket / referencia_bucket).
// Esto ademas elimina la "onda cuadrada" (minutos alternando 0/100) en clientes
// con trafico intermitente.
// ======================================================================================
const MAX_PTS = 720;          // techo de puntos en pantalla
const MIN_PTS = 30;           // piso de puntos (no agregar de mas)
const TX_POR_BUCKET = 60;     // volumen minimo por bucket para tasa estable
let kAgg = Math.ceil(tiempos.length / MAX_PTS);
{
  const txTot = totalTx.reduce((a, b) => a + b, 0);
  const avgMin = txTot / Math.max(tiempos.length, 1);
  if (avgMin > 0 && avgMin < TX_POR_BUCKET) {
    kAgg = Math.max(kAgg, Math.ceil(TX_POR_BUCKET / avgMin));
  }
  kAgg = Math.max(1, Math.min(kAgg, Math.max(1, Math.floor(tiempos.length / MIN_PTS))));
}
if (kAgg > 1) {
  const k = kAgg;
  const T = [], AC = [], H = [], TT = [], RV = [], CB = [], ZS = [];
  for (let i = 0; i < tiempos.length; i += k) {
    const j = Math.min(i + k, tiempos.length);
    let tt = 0, rvs = 0, hs = 0, hn = 0, cb = 0, zb = null;
    for (let q = i; q < j; q++) {
      tt += totalTx[q]; rvs += reversos[q];
      if (historico[q] != null) { hs += historico[q]; hn++; }
      if (cambio[q] === 1) { cb = 1; if (zScore[q] != null) zb = zScore[q]; }
    }
    T.push(tiempos[i]);
    TT.push(tt); RV.push(rvs);
    H.push(hn ? hs : null);                                   // referencia agregada del bucket
    AC.push(hn && hs > 0 ? Math.round(10000 * tt / hs) / 100 : null);
    CB.push(cb); ZS.push(zb);
  }
  tiempos = T; actividad = AC; historico = H; totalTx = TT;
  reversos = RV; cambio = CB; zScore = ZS;
}

const nPts = tiempos.length;
const pocosPuntos = nPts <= 220;
const bucketMin = Math.max(1, Math.ceil(tiemposRaw.length / Math.max(nPts, 1)));

// ---------- CLIENTE / FILTROS ----------
const cuitValues = cuitRaw.filter(v => v != null).map(v => String(v).replace(/[^0-9]/g, ""));
const uniqueCuits = [...new Set(cuitValues)];
let cliente = GLOBAL_CLIENTE;

const selectedCliente = cleanValue(rv("${cuit:label}")) || cleanValue(rv("${cuit:raw}"));

if (selectedCliente) {
  const c = String(selectedCliente).replace(/[^0-9]/g, "");
  if (CLIENTES[c]) cliente = CLIENTES[c];
  else if (c && c !== "1" && c !== "-1") cliente = { nombre: `CUIT ${c}`, color: textSec };
  else cliente = GLOBAL_CLIENTE;
} else if (uniqueCuits.length === 1 && uniqueCuits[0] && uniqueCuits[0] !== "1" && uniqueCuits[0] !== "-1") {
  const c = uniqueCuits[0];
  cliente = CLIENTES[c] || { nombre: `CUIT ${c}`, color: textSec };
}

const selectedEst = cleanValue(rv("${establecimiento:raw}")) || cleanValue(String(establecimientoRaw[0] ?? ""));
const selectedMarcaRaw = cleanValue(rv("${marca:raw}")) || cleanValue(String(marcaRaw[0] ?? ""));
const selectedMarca = selectedMarcaRaw ? prettyMarca(selectedMarcaRaw) : null;

const filtroTxt = [
  cliente.nombre,
  selectedEst ? `Est. ${selectedEst}` : "Todos los est.",
  selectedMarca || "Todas las marcas"
].join(" · ");

// ---------- RANGO ----------
const rangoDesde = desdeRaw.length ? desdeRaw[0] : tiempos[0];
const rangoHasta = hastaRaw.length ? hastaRaw[0] : tiempos[tiempos.length - 1];

const rangoTxt = rangoDesde && rangoHasta
  ? `${fmtFechaHoraCorta(rangoDesde)} - ${fmtFechaHoraCorta(rangoHasta)}`
  : "rango seleccionado";

const rangoTooltip = rangoDesde && rangoHasta
  ? `${fmtFechaHora(rangoDesde)} - ${fmtFechaHora(rangoHasta)}`
  : "rango seleccionado";

const spanMs = (() => {
  const a = new Date(tiempos[0]).getTime();
  const b = new Date(tiempos[tiempos.length - 1]).getTime();
  return (Number.isFinite(a) && Number.isFinite(b)) ? (b - a) : 0;
})();
const ejeConFecha = spanMs > 36 * 3600 * 1000;

// ======================================================================================
// v2 · ESCALA ADAPTATIVA DEL EJE IZQUIERDO
// El nivel de actividad rara vez baja de 40-50%: fijar el eje en 0-100 aplasta la
// linea en la mitad superior. Se ajusta a la banda real con margen (piso minimo 0).
// ======================================================================================
const bandVals = [];
for (const v of actividad) if (v != null && Number.isFinite(v)) bandVals.push(v);

let yMinL = 0, yMaxL = 100;
if (bandVals.length) {
  let mn = bandVals[0], mx = bandVals[0];
  for (const v of bandVals) { if (v < mn) mn = v; if (v > mx) mx = v; }
  const pad = Math.max((mx - mn) * 0.25, 2);
  yMinL = Math.max(0, Math.floor(mn - pad));
  yMaxL = Math.ceil(mx + pad);
  if (yMaxL - yMinL < 5) {
    yMinL = Math.max(0, yMinL - 3);
    yMaxL = yMaxL + 3;
  }
}

// ---------- SERIES ----------
const actividadConPuntos = actividad.map((v, i) => {
  if (v == null) return [tiempos[i], null];
  if (cambio[i] === 1) {
    const hist = historico[i];
    const esPositivo = hist == null ? v >= 95 : totalTx[i] >= hist;
    return {
      value: [tiempos[i], v],
      symbol: "circle",
      symbolSize: 9,
      itemStyle: {
        color: esPositivo ? palette.positivo : palette.negativo,
        borderColor: bg, borderWidth: 1.5
      }
    };
  }
  return [tiempos[i], v];
});

const historicoSeries = tiempos.map((t, i) => [t, historico[i]]);
const totalTxSeries = tiempos.map((t, i) => [t, totalTx[i]]);
const reversosSeries = tiempos.map((t, i) => [t, reversos[i]]);

let maxTx = 1, maxRev = 1, maxHist = 1;
for (const v of totalTx) if (v > maxTx) maxTx = v;
for (const v of reversos) if (v > maxRev) maxRev = v;
for (const v of historico) if (v != null && v > maxHist) maxHist = v;
const maxRight = Math.max(maxTx, maxRev, maxHist, 1);

// ---------- TOOLTIP ----------
function tooltipFormatter(params) {
  const arr = Array.isArray(params) ? params : [params];
  if (!arr.length) return "";

  const idx = arr[0]?.dataIndex ?? 0;
  const t = tiempos[idx];

  const act = actividad[idx];
  const hist = historico[idx];
  const tx = totalTx[idx];
  const rev = reversos[idx];
  const z = zScore[idx];

  const diferenciaTx = hist != null ? tx - hist : null;
  const pctVsHist = (hist && hist !== 0) ? (100.0 * tx / hist) : null;

  let out = `
    <div style="min-width:315px;max-width:455px">
      <div style="font-weight:800;color:${text};margin-bottom:5px">
        ${fmtFechaHora(t)}${bucketMin > 1 ? ` <span style="color:${textSec};font-weight:400;font-size:10px">(bucket ${bucketMin} min)</span>` : ""}
      </div>
      <div style="color:${textSec};font-size:10.5px;margin-bottom:8px;line-height:1.4">
        ${esc(short(filtroTxt, 82))}<br/>
        ${esc(rangoTooltip)}
      </div>
      <div style="color:${textSec};font-size:11px;line-height:1.55">
        <div>${bullet(palette.actividad)}Nivel de actividad:
          <b style="color:${text}">${act == null ? "—" : fmtPct(act)}</b>
        </div>
        <div>${bullet(palette.tx)}Transacciones:
          <b style="color:${text}">${fmtNum(tx)}</b>
        </div>
        <div>${bullet(palette.historico)}Mediana historica:
          <b style="color:${text}">${hist == null ? "—" : fmtNum(hist)}</b>
        </div>
        <div>${bullet(palette.reversos)}Reversos:
          <b style="color:${text}">${fmtNum(rev)}</b>
        </div>
      </div>
  `;

  if (z != null || cambio[idx] === 1 || diferenciaTx != null) {
    const esPositivo = diferenciaTx != null ? diferenciaTx >= 0 : false;
    const colorCambio = esPositivo ? palette.positivo : palette.negativo;
    out += `
      <div style="border-top:1px solid rgba(148,163,184,0.16);margin-top:8px;padding-top:7px;color:${textSec};font-size:11px;line-height:1.45;">
        Diferencia vs historico:
        <b style="color:${colorCambio}">
          ${diferenciaTx == null ? "—" : `${diferenciaTx >= 0 ? "+" : ""}${fmtNum(diferenciaTx)} tx`}
        </b><br/>
        Ratio vs historico:
        <b style="color:${text}">${pctVsHist == null ? "—" : fmtPct(pctVsHist)}</b><br/>
        Z-score robusto:
        <b style="color:${cambio[idx] === 1 ? colorCambio : text}">${z == null ? "—" : z.toFixed(2)}</b>
        ${cambio[idx] === 1
        ? `<br/><b style="color:${colorCambio}">${esPositivo ? "Actividad por encima de lo habitual" : "Actividad por debajo de lo habitual"}</b>`
        : ""}
      </div>
    `;
  }

  out += `</div>`;
  return out;
}

// ---------- GRAPHICS ----------
const graphics = [];

graphics.push({
  type: "text", left: 12, top: 8,
  style: { text: "Nivel de actividad", fill: aqua, font: "bold 13px sans-serif" },
  silent: true
});

graphics.push({
  type: "text", left: 12, top: 25,
  style: {
    text: `${rangoTxt} · ${bucketMin > 1 ? `serie cada ${bucketMin} min` : "total tx vs historico"} · eje ${yMinL}-${yMaxL}%`,
    fill: textSec, font: "10px sans-serif"
  },
  silent: true
});

graphics.push({
  type: "text", right: 16, top: 8,
  style: { text: cliente.nombre, fill: cliente.color, font: "bold 10.5px sans-serif", textAlign: "right" },
  silent: true
});

graphics.push({
  type: "text", right: 16, top: 25,
  style: {
    text: short(`${selectedEst ? `Est. ${selectedEst}` : "Todos los est."} · ${selectedMarca || "Todas las marcas"}`, 70),
    fill: textSoft, font: "10px sans-serif", textAlign: "right"
  },
  silent: true
});

graphics.push({
  type: "text", left: "center", bottom: 8,
  style: { text: filtroTxt, fill: cliente.color, font: "bold 10px sans-serif", textAlign: "center" },
  silent: true
});

// ---------- RETURN ----------
return {
  backgroundColor: bg,

  color: [palette.actividad, palette.historico, palette.tx, palette.reversos],

  title: {
    text: "Actual vs historico",
    left: 12, top: 43,
    textStyle: { color: text, fontSize: 12, fontWeight: 800 }
  },

  legend: {
    top: 65, left: 12, itemWidth: 7, itemHeight: 7, icon: "circle", itemGap: 10,
    textStyle: { color: textSec, fontSize: 8.5 },
