};

const GLOBAL_CLIENTE = { nombre: "PAYWAY GENERAL", color: textSec };

const series = context.panel?.data?.series || [];
const s = series[0];

function valuesOfField(f) {
  if (!f) return [];
  if (typeof f.values?.toArray === "function") return f.values.toArray();
  return Array.from(f.values || []);
}

function normName(v) {
  return String(v ?? "").trim().toLowerCase();
}

function fieldAny(names) {
  if (!s || !s.fields) return [];
  const wanted = names.map(normName);

  for (const f of s.fields) {
    if (wanted.includes(normName(f.name))) {
      return valuesOfField(f);
    }
  }
  return [];
}

function firstAny(names, fallback = null) {
  const vals = fieldAny(names);
  return vals.length ? vals[0] : fallback;
}

function num(v, d = 0) {
  const x = Number(v);
  return Number.isFinite(x) ? x : d;
}

function fmtNum(v) {
  return num(v).toLocaleString("es-AR");
}

function fmtShort(v) {
  const n = num(v, 0);
  if (n >= 1000000) return `${(n / 1000000).toFixed(2)}M`;
  if (n >= 1000) return `${(n / 1000).toFixed(1)}k`;
  return fmtNum(n);
}

function fmtPct(v, dec = 1) {
  return `${num(v).toFixed(dec)}%`;
}

function esc(v) {
  return String(v ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function cleanText(v) {
  return String(v ?? "")
    .replace(/Ã¡/g, "a")
    .replace(/Ã©/g, "e")
    .replace(/Ã­/g, "i")
    .replace(/Ã³/g, "o")
    .replace(/Ãº/g, "u")
    .replace(/Ã±/g, "n")
    .replace(/Â/g, "")
    .replace(/â€“/g, "-")
    .replace(/â€”/g, "-");
}

function short(v, max = 60) {
  const t = cleanText(v);
  return t.length > max ? `${t.slice(0, max - 1)}...` : t;
}

function fmtFechaHora(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  const fecha = d.toLocaleDateString("es-AR", { day: "2-digit", month: "2-digit", year: "numeric" });
  const hora = d.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false });
  return `${fecha} ${hora}`;
}

function fmtFechaHoraCorta(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  const fecha = d.toLocaleDateString("es-AR", { day: "2-digit", month: "2-digit" });
  const hora = d.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false });
  return `${fecha} ${hora}`;
}

function prettyMarca(v) {
  const x = cleanText(v || "-1").toUpperCase();
  if (!x || x === "-1" || x === "ALL" || x === "TODAS LAS MARCAS") return "Todas las marcas";

  const map = {
    VISA: "Visa",
    MASTERCARD: "Mastercard",
    AMEX: "Amex",
    CABAL_DISCOVER: "Cabal / Discover",
    CABAL: "Cabal",
    DISCOVER: "Cabal / Discover",
    UPI: "UPI",
    OTRAS: "Otras",
    OTRA: "Otras"
  };

  return map[x] || x;
}

function prettyEst(v) {
  const x = cleanText(v || "-1").trim();
  if (!x || x === "-1" || x.toUpperCase() === "ALL") return "Todos los est.";
  return `Est. ${x}`;
}

function normalizeCuadrante(v) {
  const raw = cleanText(v ?? "Otros").trim();
  const upper = raw.toUpperCase();

  if (COLORS[raw]) return raw;
  if (upper === "RIESGO EMISOR") return "Riesgo Emisor";
  if (upper === "OPERATIVO EMISOR") return "Operativo Emisor";
  if (upper === "RIESGO ADQUIRENTE") return "Riesgo Adquirente";
  if (upper === "OPERATIVO ADQUIRENTE") return "Operativo Adquirente";
  if (upper === "EMISOR NO CATALOGADO") return "Emisor no catalogado";
  if (upper === "CODIGO EMISOR DE OTRAS MARCAS") return "Emisor no catalogado";
  if (upper === "CODIGO EMISOR - MARCA NO MAPEADA") return "Emisor no catalogado";
  if (upper === "OTROS") return "Otros";
  if (upper === "NO CLASIFICADO") return "No Clasificado";

  return raw || "Otros";
}

function rv(str) {
  try {
    if (context?.grafana?.replaceVariables) return context.grafana.replaceVariables(str);
  } catch (e) { }
  return str;
}

function cleanValue(v) {
  const x = String(v ?? "").trim();
  if (!x) return null;
  if (x === "-1") return null;
  if (x.toUpperCase() === "ALL") return null;
  if (x.toUpperCase() === "TODAS LAS MARCAS") return null;
  return x;
}

function emptyState(msg = "Sin rechazos en el rango") {
  return {
    backgroundColor: bg,
    graphic: [
      {
        type: "text",
        left: 12,
        top: 8,
        style: {
          text: "Cuadrantes",
          fill: aqua,
          font: "800 13px sans-serif"
        },
        silent: true
      },
      {
        type: "text",
        left: "center",
        top: "middle",
        style: {
          text: msg,
          fill: textSec,
          font: "600 12px sans-serif",
          textAlign: "center"
        },
        silent: true
      }
    ],
    xAxis: { show: false },
    yAxis: { show: false },
    series: [],
    animation: false
  };
}

if (!s || !s.fields || s.fields.length === 0) {
  return emptyState();
}

// ---------- CAMPOS ROBUSTOS ----------
const cuadrantesRaw = fieldAny([
  "cuadrante",
  "quadrant",
  "cuadrante_mapeado",
  "tipo_cuadrante"
]);

const denegacionesRaw = fieldAny([
  "denegaciones_actuales",
  "rechazos",
  "denegadas",
  "total_denegadas",
  "total_rechazos",
  "cantidad",
  "count",
  "rechazos_codigo"
]);

const porcentajeRaw = fieldAny([
  "porcentaje_rechazo",
  "pct_denegadas",
  "pct_rechazos",
  "participacion",
  "participacion_pct"
]);

const rangoDesdeRaw = firstAny(["rango_desde", "desde", "fecha_desde"], null);
const rangoHastaRaw = firstAny(["rango_hasta", "hasta", "fecha_hasta"], null);

const cuitRaw = firstAny(["cuit"], "-1");
const establecimientoRaw = firstAny(["establecimiento", "establecimiento_filtro", "nro_establecimiento"], "-1");
const marcaRaw = firstAny(["marca", "marca_filtro", "brand"], "-1");

if (!cuadrantesRaw.length || !denegacionesRaw.length) {
  return emptyState();
}

// ---------- CONTEXTO ----------
let cliente = GLOBAL_CLIENTE;

const selectedCliente =
  cleanValue(rv("${cuit:raw}")) ||
  cleanValue(rv("${cuit:label}"));

if (selectedCliente) {
  const c = String(selectedCliente).replace(/[^0-9]/g, "");
  if (CLIENTES[c]) cliente = CLIENTES[c];
  else if (c && c !== "1" && c !== "-1") cliente = { nombre: `CUIT ${c}`, color: textSec };
} else {
  const c = String(cuitRaw ?? "-1").replace(/[^0-9]/g, "");
  if (c && c !== "1" && c !== "-1") cliente = CLIENTES[c] || { nombre: `CUIT ${c}`, color: textSec };
}

const selectedEst =
  cleanValue(rv("${establecimiento:raw}")) ||
  cleanValue(String(establecimientoRaw ?? ""));

const selectedMarcaRaw =
  cleanValue(rv("${marca:raw}")) ||
  cleanValue(String(marcaRaw ?? ""));

const estVisible = selectedEst ? `Est. ${selectedEst}` : prettyEst(establecimientoRaw);
const marcaVisible = selectedMarcaRaw ? prettyMarca(selectedMarcaRaw) : prettyMarca(marcaRaw);

const rangoTxt =
  rangoDesdeRaw && rangoHastaRaw
    ? `${fmtFechaHoraCorta(rangoDesdeRaw)} - ${fmtFechaHoraCorta(rangoHastaRaw)}`
    : "rango seleccionado";

const rangoTooltip =
  rangoDesdeRaw && rangoHastaRaw
    ? `${fmtFechaHora(rangoDesdeRaw)} - ${fmtFechaHora(rangoHastaRaw)}`
    : "rango seleccionado";

const filtroTxt = [
  cliente.nombre || "PAYWAY GENERAL",
  estVisible,
  marcaVisible
].join(" · ");

// ---------- DATA ----------
let rows = [];

for (let i = 0; i < denegacionesRaw.length; i++) {
  const cuadrante = normalizeCuadrante(cuadrantesRaw[i]);
  const value = num(denegacionesRaw[i], 0);
  const pct = porcentajeRaw.length ? num(porcentajeRaw[i], null) : null;

  if (value <= 0) continue;
  if (cuadrante === "No Clasificado") continue;

  rows.push({
    name: cuadrante,
    value,
    pct,
    itemStyle: {
      color: COLORS[cuadrante] || slate
    }
  });
}

rows.sort((a, b) => {
  const ia = ORDER.indexOf(a.name) === -1 ? 999 : ORDER.indexOf(a.name);
  const ib = ORDER.indexOf(b.name) === -1 ? 999 : ORDER.indexOf(b.name);
  if (ia !== ib) return ia - ib;
  return b.value - a.value;
});

const total = rows.reduce((a, b) => a + b.value, 0);

rows = rows.map(r => ({
  ...r,
  pctFinal: r.pct === null || !Number.isFinite(r.pct)
    ? total > 0 ? (100 * r.value / total) : 0
    : r.pct
}));

const top = [...rows].sort((a, b) => b.value - a.value)[0];
const topPct = top ? top.pctFinal : 0;

if (!rows.length || total === 0) {
  return emptyState();
}

// ---------- RESPONSIVE ----------
const W = context?.width || 520;
const H = context?.height || 260;

const tiny = W < 360 || H < 190;
const small = W < 460 || H < 230;
const wide = W >= 620;

const headerFont = tiny ? 10.5 : 13;
const subFont = tiny ? 8 : 9.5;
const legendFont = tiny ? 7.5 : small ? 8 : 8.7;

const headerLeft = 12;
const headerTop = 8;
const subTop = tiny ? 23 : 27;
const filterTop = tiny ? 39 : 45;

let pieCenter;
let pieRadius;
let legendOrient;
let legendLeft;
let legendTop;
let legendRight;

if (tiny) {
  pieCenter = ["63%", "61%"];
  pieRadius = ["30%", "48%"];
  legendOrient = "vertical";
  legendLeft = 10;
  legendTop = 66;
  legendRight = null;
} else if (small) {
  pieCenter = ["63%", "61%"];
  pieRadius = ["33%", "53%"];
  legendOrient = "vertical";
  legendLeft = 10;
  legendTop = 70;
  legendRight = null;
} else if (wide) {
  pieCenter = ["68%", "59%"];
  pieRadius = ["41%", "64%"];
  legendOrient = "vertical";
  legendLeft = 12;
  legendTop = 82;
  legendRight = null;
} else {
  pieCenter = ["64%", "59%"];
  pieRadius = ["38%", "60%"];
  legendOrient = "vertical";
  legendLeft = 12;
  legendTop = 80;
  legendRight = null;
}

function tooltipFormatter(p) {
  const pct = total > 0 ? (100 * p.value / total) : 0;

  return `
    <div style="min-width:260px;max-width:400px">
      <div style="font-weight:800;color:${text};margin-bottom:6px">${esc(p.name)}</div>
      <div style="color:${textSec};font-size:10.5px;margin-bottom:8px;line-height:1.45">
        ${esc(filtroTxt)}<br/>
        ${esc(rangoTooltip)}
      </div>
      <div style="color:${textSec};font-size:11px;line-height:1.55">
        Rechazos: <b style="color:${text}">${fmtNum(p.value)}</b><br/>
        Participacion: <b style="color:${text}">${fmtPct(pct, 1)}</b>
      </div>
    </div>
  `;
}

return {
  backgroundColor: bg,

  legend: {
    show: true,
    orient: legendOrient,
    left: legendLeft,
    right: legendRight,
    top: legendTop,
    itemWidth: tiny ? 6 : 7,
    itemHeight: tiny ? 6 : 7,
    icon: "circle",
    itemGap: tiny ? 5 : 8,
    textStyle: {
      color: textSec,
      fontSize: legendFont
    },
    formatter: function (name) {
      const r = rows.find(x => x.name === name);
      if (!r) return name;
      const labelMax = tiny ? 14 : small ? 18 : 24;
      return `${short(name, labelMax)}  ${fmtPct(r.pctFinal, 1)}`;
    },
    data: rows.map(r => r.name)
  },

  tooltip: {
    trigger: "item",
    appendToBody: false,
    confine: true,
    enterable: false,
    backgroundColor: "rgba(11,15,24,0.82)",
    borderColor: "rgba(0,244,196,0.55)",
    borderWidth: 1,
    padding: 10,
    textStyle: {
      color: text,
      fontSize: 11,
      fontFamily: "Inter, Roboto, sans-serif"
    },
    formatter: tooltipFormatter
  },

  series: [
    {
      name: "Cuadrantes",
      type: "pie",
      radius: pieRadius,
      center: pieCenter,
