// ======================================================================================
// BUSINESS CHART — FLUJO DEL ECOSISTEMA (Sankey)
// Plataforma de Pago → Modalidad → Producto → Resultado
// Ancho del flujo = volumen · rótulos de etapa · % en nodos grandes
// ======================================================================================

const aqua="#00F4C4", amber="#E7B432", violet="#7C6AE6", coral="#CF4360";
const slate="#64748B", gray="#94A3B8", blue="#3B82F6", green="#22C55E", naranja="#FF8A5C";
const bg="#0a0e17", text="#E5E7EB", textSec="#8b93a7", textSoft="#CBD5E1";

const s=(context.panel?.data?.series||[])[0];
function vals(f){ if(!f) return []; return typeof f.values?.toArray==="function"?f.values.toArray():Array.from(f.values||[]); }
function col(n){ if(!s||!s.fields) return []; const f=s.fields.find(x=>String(x.name).toLowerCase()===n); return vals(f); }
const num=(v,d=0)=>{const x=Number(v);return Number.isFinite(x)?x:d;};
const fmtNum=v=>num(v).toLocaleString("es-AR");
const fmtPct=v=>`${num(v).toFixed(1)}%`;
const fmtCorto=v=>{const x=num(v);
  if(x>=1e6)return (x/1e6).toLocaleString("es-AR",{maximumFractionDigits:2})+" M";
  if(x>=1e3)return (x/1e3).toLocaleString("es-AR",{maximumFractionDigits:1})+" k";
  return fmtNum(x);};
const esc=v=>String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
function fmtFechaHora(v){const d=new Date(v);return isNaN(d.getTime())?String(v):d.toLocaleString("es-AR",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit",hour12:false});}

// ---------- filtros del tablero (para el header) ----------
function rv(str){ try{ if(context?.grafana?.replaceVariables) return context.grafana.replaceVariables(str);}catch(e){} return str; }
function cleanValue(v){ const x=String(v??"").trim(); if(!x||x==="-1")return null;
  const u=x.toUpperCase(); if(u==="ALL"||u==="TODAS LAS MARCAS"||u==="$__ALL"||x.startsWith("${"))return null; return x; }
function prettyMarca(v){ const x=String(v??"").toUpperCase();
  const m={VISA:"Visa",MASTERCARD:"Mastercard",AMEX:"Amex",CABAL_DISCOVER:"Cabal / Discover",UPI:"UPI",OTRAS:"Otras"};
  return m[x]||v; }
const selCuit=cleanValue(rv("${cuit:raw}"));
const selEst=cleanValue(rv("${establecimiento:raw}"));
const selMarca=cleanValue(rv("${marca:raw}"));
const filtroTxt=[ selCuit?`CUIT ${String(selCuit).replace(/[^0-9]/g,"")}`:"PAYWAY GENERAL",
  selEst?`Est. ${selEst}`:"Todos los est.",
  selMarca?prettyMarca(selMarca):"Todas las marcas" ].join(" · ");

function sinDatos(){ return { backgroundColor:bg, graphic:[
  {type:"text",left:12,top:8,style:{text:"Flujo del ecosistema",fill:aqua,font:"bold 13px sans-serif"},silent:true},
  {type:"text",left:"center",top:"middle",style:{text:"Sin transaccionamiento en el rango",fill:textSec,font:"800 12px sans-serif",textAlign:"center"},silent:true}
], xAxis:{show:false},yAxis:{show:false},series:[],animation:false }; }
if(!s||!s.fields||s.fields.length===0) return sinDatos();

const gws=col("gateway"), mods=col("modalidad"), prods=col("producto"), ress=col("resultado"), txs=col("tx");
if(!gws.length) return sinDatos();
const rangoTxt=`${fmtFechaHora(col("rango_desde")[0])} – ${fmtFechaHora(col("rango_hasta")[0])}`;

// ---------- agregación ----------
const SEP=String.fromCharCode(1);           // separador origen→destino (no aparece en los datos)
const L=[{},{},{}];           // links por etapa
const vol={};                 // volumen por nodo
const etapa={};               // nodo -> índice de etapa
let total=0, aprobadas=0;
for(let i=0;i<gws.length;i++){
  const g=String(gws[i]), m=String(mods[i]), p=String(prods[i]), r=String(ress[i]), t=num(txs[i]);
  if(!t) continue;
  total+=t; if(r==="Aprobada") aprobadas+=t;
  L[0][g+SEP+m]=(L[0][g+SEP+m]||0)+t;
  L[1][m+SEP+p]=(L[1][m+SEP+p]||0)+t;
  L[2][p+SEP+r]=(L[2][p+SEP+r]||0)+t;
  vol[g]=(vol[g]||0)+t; vol[m]=(vol[m]||0)+t; vol[p]=(vol[p]||0)+t; vol[r]=(vol[r]||0)+t;
  etapa[g]=0; etapa[m]=1; etapa[p]=2; etapa[r]=3;
}
if(!total) return sinDatos();

// ---------- colores ----------
const FIJOS={
  "Aprobada":green, "Denegada":coral,
  "Débito Automático":amber, "E-commerce":blue, "Presente":aqua, "Indeterminado":slate,
  "Crédito":aqua, "Débito":blue, "Prepaga":amber, "Marca Privada":violet, "Otro producto":gray,
  "NO MAPEADO":coral, "Otras plataformas":slate, "DA · batch":amber
};
const PAL=[blue,violet,"#5EEAD4",naranja,amber,"#93C5FD",green,"#C084FC",aqua,gray];
let pi=0;
const nombres=Object.keys(vol);
const colorDe={};
for(const n of nombres) colorDe[n]= FIJOS[n] || PAL[(pi++)%PAL.length];

// ---------- nodos ----------
const nodes=nombres.map(n=>{
  const pct=100*vol[n]/total;
  const et=etapa[n];
  return {
    name:n,
    itemStyle:{ color:colorDe[n], borderWidth:0 },
    label:{
      position: et===3 ? "left" : "right",
      color: n==="NO MAPEADO" ? coral : textSoft,
      fontSize: 10,
      fontWeight: pct>=15 ? 700 : 400,
      formatter: pct>=2.5 ? `${n}  ${fmtCorto(vol[n])} · ${pct.toFixed(0)}%` : `${n}  ${fmtCorto(vol[n])}`
    }
  };
});

// ---------- links (sin self-loops) ----------
const links=[];
for(let e=0;e<3;e++){
  for(const k in L[e]){
    const [a,b]=k.split(SEP);
    if(a===b) continue;
    links.push({source:a,target:b,value:L[e][k]});
  }
}

// ---------- rótulos de etapa ----------
const W=context?.width||900;
const LEFT=14, RIGHT=118, NODEW=12;
const util=Math.max(120, W-LEFT-RIGHT-NODEW);
const ETAPAS=["PLATAFORMA DE PAGO","MODALIDAD","PRODUCTO","RESULTADO"];
const rotulos=ETAPAS.map((t,i)=>({
  type:"text", left: LEFT + i*(util/3) + (i===3?-30:0), top: 44,
  style:{ text:t, fill:"rgba(139,147,167,0.75)", font:"700 9px sans-serif", letterSpacing:1 }, silent:true
}));

const taa=100*aprobadas/total;
const colTaa = taa>=95?green : taa>=85?amber : coral;

return {
  backgroundColor:bg,
  graphic:[
    {type:"text",left:12,top:8,style:{text:"Flujo del ecosistema",fill:aqua,font:"bold 13px sans-serif"},silent:true},
    {type:"text",left:12,top:25,style:{text:`${rangoTxt} · ${fmtCorto(total)} tx · el ancho de cada flujo es el volumen`,fill:textSec,font:"10px sans-serif"},silent:true},
    {type:"text",right:16,top:8,style:{text:filtroTxt,fill:textSoft,font:"10px sans-serif",textAlign:"right"},silent:true},
    {type:"text",right:16,top:24,style:{text:`TAA ${fmtPct(taa)}`,fill:colTaa,font:"700 11px sans-serif",textAlign:"right"},silent:true},
    ...rotulos
  ],
  tooltip:{
    trigger:"item", confine:true,
    backgroundColor:"rgba(11,15,24,0.88)", borderColor:"rgba(0,244,196,0.55)", borderWidth:1, padding:9,
    textStyle:{color:text,fontSize:11},
    formatter:p=>{
      if(p.dataType==="edge"){
        const v=p.data.value;
        return `<b>${esc(p.data.source)}</b> → <b>${esc(p.data.target)}</b><br/>`+
               `${fmtNum(v)} tx · ${fmtPct(100*v/total)} del total<br/>`+
               `<span style="color:${textSec};font-size:10px">${fmtPct(100*v/Math.max(vol[p.data.source],1))} de ${esc(p.data.source)}</span>`;
      }
      return `<b>${esc(p.name)}</b><br/>${fmtNum(vol[p.name])} tx · ${fmtPct(100*vol[p.name]/total)} del total`;
    }
  },
  series:[{
    type:"sankey",
    left:LEFT, right:RIGHT, top:58, bottom:12,
    nodeWidth:NODEW, nodeGap:10,
    nodeAlign:"justify",
    layoutIterations:48,
    emphasis:{ focus:"adjacency", lineStyle:{opacity:0.62} },
    lineStyle:{ color:"gradient", opacity:0.34, curveness:0.48 },
    labelLayout:{ hideOverlap:true },
    data:nodes, links:links,
    animation:false
  }],
  animation:false
};

