  "30715221159": { nombre: "PAGOSYA", color: violet },
  "30695542476": { nombre: "PAN AMERICAN ENERGY", color: amber },
  "30708743514": { nombre: "PAYU", color: violet },
  "30707743987": { nombre: "PLUS PAGOS", color: violet },
  "30704950345": { nombre: "PROVINCIA NET", color: violet },
  "30659863789": { nombre: "SERV. ELECTRONICO DE PAGO", color: violet },
  "30612865333": { nombre: "VITAL", color: aqua },
  "30589621499": { nombre: "MAKRO", color: aqua },
  "30654855168": { nombre: "SWISS MEDICAL", color: green },
  "30640897267": { nombre: "TELECENTRO", color: blue },
  "30639453738": { nombre: "TELECOM", color: blue },
  "30678814357": { nombre: "MOVISTAR", color: blue },
  "33690765549": { nombre: "TICKETEK", color: green },
  "30715778722": { nombre: "TODOTRAIL", color: amber },
  "30716370964": { nombre: "VIUMI", color: amber },
  "30655534462": { nombre: "VISUAR", color: violet }
};

const GLOBAL_CLIENTE = { nombre: "PAYWAY GENERAL", color: textSoft };

// ---------- DATA HELPERS ----------
const series0 = context.panel?.data?.series || [];
const s = series0[0];

function valuesOfField(f) {
  if (!f) return [];
  if (typeof f.values?.toArray === "function") return f.values.toArray();
  return Array.from(f.values || []);
}
function fieldAny(names) {
  if (!s || !s.fields) return [];
  for (const name of names) {
    const f = s.fields.find(x => String(x.name).toLowerCase() === String(name).toLowerCase());
    const vals = valuesOfField(f);
    if (vals.length) return vals;
  }
  return [];
}
const num = (v, d = 0) => { const x = Number(v); return Number.isFinite(x) ? x : d; };
const fmtNum = v => num(v).toLocaleString("es-AR");
const fmtPct = v => `${num(v).toFixed(1)}%`;
const esc = v => String(v ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");

function fmtFechaHora(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  return d.toLocaleString("es-AR", { day:"2-digit", month:"2-digit", hour:"2-digit", minute:"2-digit", hour12:false });
}

function prettyMarca(v) {
  const x = String(v ?? "-").toUpperCase();
  const map = { VISA:"Visa", MASTERCARD:"Mastercard", AMEX:"Amex", CABAL_DISCOVER:"Cabal / Discover", UPI:"UPI", OTRAS:"Otras" };
  return map[x] || v;
}

// ---------- VARIABLES GRAFANA ----------
function rv(str) {
  try { if (context?.grafana?.replaceVariables) return context.grafana.replaceVariables(str); } catch (e) {}
  return str;
}
function cleanValue(v) {
  const x = String(v ?? "").trim();
  if (!x || x === "-1") return null;
  const up = x.toUpperCase();
  if (up === "ALL" || up === "TODAS LAS MARCAS" || up === "$__ALL" || x.startsWith("${")) return null;
  return x;
}

const selectedEst = cleanValue(rv("${establecimiento:raw}"));
const selectedMarca = cleanValue(rv("${marca:raw}"));
const selectedClienteRaw = cleanValue(rv("${cuit:raw}")) || cleanValue(rv("${cuit:label}"));

let cliente = GLOBAL_CLIENTE;
if (selectedClienteRaw) {
  const cuitNorm = String(selectedClienteRaw).replace(/[^0-9]/g, "");
  cliente = CLIENTES[cuitNorm] || { nombre: `CUIT ${cuitNorm}`, color: textSoft };
}

const filtroTxt = [
  cliente.nombre,
  selectedEst ? `Est. ${selectedEst}` : "Todos los est.",
  selectedMarca ? prettyMarca(selectedMarca) : "Todas las marcas"
].join(" · ");

// ---------- EMPTY ----------
function sinDatos() {
  return {
    backgroundColor: bg,
    graphic: [
      { type:"text", left:12, top:8, style:{ text:"Tipo de Producto", fill:aqua, font:"800 12px sans-serif" }, silent:true },
      { type:"text", left:"center", top:"middle", style:{ text:"Sin transaccionamiento", fill:textSec, font:"800 12px sans-serif", textAlign:"center" }, silent:true }
    ],
    xAxis:{ show:false }, yAxis:{ show:false }, series:[], animation:false
  };
}

if (!s || !s.fields || s.fields.length === 0) return sinDatos();

// ---------- CAMPOS ----------
const cats = fieldAny(["categoria"]);
const totales = fieldAny(["total_tx"]).map(v => num(v));
const aprob = fieldAny(["aprobadas"]).map(v => num(v));
const deneg = fieldAny(["denegadas"]).map(v => num(v));
const tasas = fieldAny(["tasa_aprobacion"]).map(v => num(v));

const rangoTxt = `${fmtFechaHora(fieldAny(["rango_desde"])[0])} – ${fmtFechaHora(fieldAny(["rango_hasta"])[0])}`;

if (!cats.length || totales.every(v => v === 0)) return sinDatos();

const totalGeneral = totales.reduce((a, b) => a + b, 0);
const colorTasa = t => t >= 95 ? green : t >= 85 ? amber : coral;

// ---------- HEADER ----------
const graphics = [
  { type:"text", left:12, top:8, style:{ text:"Tipo de Producto", fill:aqua, font:"bold 13px sans-serif" }, silent:true },
  { type:"text", left:12, top:25, style:{ text:`${rangoTxt} · rango del selector`, fill:textSec, font:"10px sans-serif" }, silent:true },
  { type:"text", right:16, top:8, style:{ text:filtroTxt, fill:cliente.color, font:"10px sans-serif", textAlign:"right" }, silent:true },
  { type:"text", right:16, top:25, style:{ text:`${fmtNum(totalGeneral)} tx · TAA ${fmtPct(100.0*aprob.reduce((a,b)=>a+b,0)/Math.max(totalGeneral,1))}`, fill:textSec, font:"10px sans-serif", textAlign:"right" }, silent:true }
];

// ---------- TOOLTIP ----------
function tooltipFormatter(params) {
  const i = params[0].dataIndex;
