  return d.toLocaleTimeString("es-AR", { hour:"2-digit", minute:"2-digit", hour12:false });
}
function fmtFechaHora(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  return d.toLocaleString("es-AR", { day:"2-digit", month:"2-digit", hour:"2-digit", minute:"2-digit", hour12:false });
}
function prettyMarca(v) {
  const x = String(v ?? "-").toUpperCase();
  const map = { VISA:"Visa", MASTERCARD:"Mastercard", AMEX:"Amex", CABAL_DISCOVER:"Cabal / Discover", UPI:"UPI", OTRAS:"Otras" };
  return map[x] || v;
}

// ---------- VARIABLES ----------
function rv(str) {
  try { if (context?.grafana?.replaceVariables) return context.grafana.replaceVariables(str); } catch (e) {}
  return str;
}
function cleanValue(v) {
  const x = String(v ?? "").trim();
  if (!x || x === "-1") return null;
  const up = x.toUpperCase();
  if (up === "ALL" || up === "TODAS LAS MARCAS" || up === "$__ALL" || x.startsWith("${")) return null;
  return x;
}
const selectedEst = cleanValue(rv("${establecimiento:raw}"));
const selectedMarca = cleanValue(rv("${marca:raw}"));
const selectedClienteRaw = cleanValue(rv("${cuit:raw}")) || cleanValue(rv("${cuit:label}"));
let cliente = GLOBAL_CLIENTE;
if (selectedClienteRaw) {
  const cuitNorm = String(selectedClienteRaw).replace(/[^0-9]/g, "");
  cliente = CLIENTES[cuitNorm] || { nombre: `CUIT ${cuitNorm}`, color: textSoft };
}
const filtroTxt = [
  cliente.nombre,
  selectedEst ? `Est. ${selectedEst}` : "Todos los est.",
  selectedMarca ? prettyMarca(selectedMarca) : "Todas las marcas"
].join(" · ");

// ---------- EMPTY ----------
function sinDatos() {
  return {
    backgroundColor: bg,
    graphic: [
      { type:"text", left:12, top:8, style:{ text:"Modalidades · evolución", fill:aqua, font:"800 12px sans-serif" }, silent:true },
      { type:"text", left:"center", top:"middle", style:{ text:"Sin transaccionamiento", fill:textSec, font:"800 12px sans-serif", textAlign:"center" }, silent:true }
    ],
    xAxis:{ show:false }, yAxis:{ show:false }, series:[], animation:false
  };
}
if (!s || !s.fields || s.fields.length === 0) return sinDatos();

// ---------- NORMALIZACIÓN long → series ----------
const tiemposRaw = fieldAny(["time", "bk"]);
const catsRaw = fieldAny(["categoria"]);
const totRaw = fieldAny(["total_tx"]);
const aprRaw = fieldAny(["aprobadas"]);
const denRaw = fieldAny(["denegadas"]);
const tasaRaw = fieldAny(["tasa_aprobacion"]);

if (!tiemposRaw.length || !catsRaw.length) return sinDatos();

const rangoTxt = `${fmtFechaHora(fieldAny(["rango_desde"])[0])} – ${fmtFechaHora(fieldAny(["rango_hasta"])[0])}`;

const bucketSet = new Set();
const matrix = {};   // t -> cat -> total
const detail = {};   // t -> cat -> {a,d,tasa}
const catSet = new Set();

for (let i = 0; i < tiemposRaw.length; i++) {
  const t = new Date(tiemposRaw[i]).getTime();
  if (!Number.isFinite(t)) continue;
  const c = String(catsRaw[i]);
  bucketSet.add(t);
  catSet.add(c);
  if (!matrix[t]) { matrix[t] = {}; detail[t] = {}; }
  matrix[t][c] = num(totRaw[i]);
  detail[t][c] = { a: num(aprRaw[i]), d: num(denRaw[i]), tasa: num(tasaRaw[i]) };
}

const buckets = Array.from(bucketSet).sort((a, b) => a - b);
// v2: descartar el ultimo bucket si esta incompleto (evita la caida falsa al final)
if (buckets.length >= 3) {
  const pasoBk = buckets[buckets.length - 1] - buckets[buckets.length - 2];
  if (Number.isFinite(pasoBk) && pasoBk > 0 && buckets[buckets.length - 1] + pasoBk > Date.now() - 60000) {
    buckets.pop();
  }
}
const pocosPuntos = buckets.length <= 220;
const bkMin = buckets.length >= 2 ? Math.max(1, Math.round((buckets[1] - buckets[0]) / 60000)) : 15;

// orden estable: por volumen total desc
const catTotals = {};
for (const c of catSet) catTotals[c] = buckets.reduce((acc, t) => acc + num(matrix[t]?.[c]), 0);
const cats = Array.from(catSet).sort((a, b) => catTotals[b] - catTotals[a]);

if (!buckets.length || cats.every(c => catTotals[c] === 0)) return sinDatos();

const colorDe = (c, i) => COLOR_MAP[c] || PALETA[i % PALETA.length];

// ---------- HELPER QUE FALTABA ----------
// El preambulo del 141 no tiene fmtCorto (es del 151): con escalas propias los ejes
// de cada faceta necesitan etiquetas cortas o no entran en el ancho de la celda.
const fmtCorto = v => {
  const x = num(v);
  if (Math.abs(x) >= 1e6) return (x / 1e6).toLocaleString("es-AR", { maximumFractionDigits: 1 }) + " M";
  if (Math.abs(x) >= 1e3) return (x / 1e3).toLocaleString("es-AR", { maximumFractionDigits: 0 }) + " k";
  return fmtNum(x);
};

// ---------- LA UNIDAD ----------
// Cada punto de la serie es el TOTAL del bucket, no un valor por minuto. Como bkMin
// cambia con el rango (1/5/15/60), sin decirlo el panel es ambiguo.
const porMin = v => fmtNum(Math.round(num(v) / Math.max(bkMin, 1)));
const finBucket = t => fmtHora(t + Math.max(bkMin, 1) * 60000);

// ---------- ORDEN DE LAS FACETAS ----------
// Orden fijo, no por volumen: en un panel que se mira muchas veces por dia conviene
// que cada modalidad este siempre en el mismo lugar. Lo que no este en la lista
// (una categoria nueva) cae al final ordenado por volumen.
const ORDEN_MODALIDADES = ["Débito Automático", "E-commerce", "Presente", "Indeterminado"];
const catsFacetas = cats.slice().sort((a, b) => {
  const ia = ORDEN_MODALIDADES.indexOf(a), ib = ORDEN_MODALIDADES.indexOf(b);
  if (ia !== -1 && ib !== -1) return ia - ib;
  if (ia !== -1) return -1;
  if (ib !== -1) return 1;
  return catTotals[b] - catTotals[a];
});

// aprobadas acumuladas por modalidad, para la TAA del subtitulo de cada faceta
const catAprob = {};
for (const c of catsFacetas) {
  catAprob[c] = buckets.reduce((acc, t) => acc + num(detail[t] && detail[t][c] ? detail[t][c].a : 0), 0);
}

// ---------- LAYOUT DE FACETAS ----------
// Mismos numeros que el panel 151, adaptados: aca son 3 o 4 modalidades en una sola
// fila, asi que TOP puede ser mas alto (no hay una segunda fila que acomodar) y el
// encabezado del panel queda holgado.
const n = catsFacetas.length;
const COLS = Math.min(4, Math.max(1, n)), ROWS = Math.ceil(n / COLS);
const TOP = ROWS === 1 ? 30 : 22, BOT = 6, GAPX = 4.5, GAPY = 13;
const usableW = 100 - 4 - 4 - (COLS - 1) * GAPX;
const cellW = usableW / COLS;
const usableH = 100 - TOP - BOT - (ROWS - 1) * GAPY;
const cellH = usableH / ROWS;

const grids = [], xAxes = [], yAxes = [], chartSeries = [], titles = [];

catsFacetas.forEach((c, i) => {
  const col = i % COLS, fila = Math.floor(i / COLS);
  const left = 4 + col * (cellW + GAPX);
  const top = TOP + fila * (cellH + GAPY);
  const col_ = colorDe(c, cats.indexOf(c));

  grids.push({ left: left + "%", top: top + "%", width: cellW + "%", height: cellH + "%" });

  xAxes.push({
    gridIndex: i, type: "time", boundaryGap: false,
    axisLine: { lineStyle: { color: "rgba(148,163,184,0.14)" } },
    axisTick: { show: false }, splitLine: { show: false },
    axisLabel: fila === ROWS - 1
      ? { color: textSec, fontSize: 7.5, hideOverlap: true, formatter: v => fmtHora(v) }
      : { show: false }
  });

  // min:0 y escala automatica por faceta: esto es lo que hace que se vea la
  // variacion de E-commerce aunque Debito Automatico sea 4 veces mas grande
  yAxes.push({
    gridIndex: i, type: "value", min: 0, splitNumber: 2,
    axisLine: { show: false }, axisTick: { show: false },
    splitLine: { show: true, lineStyle: { color: "rgba(148,163,184,0.10)" } },
    axisLabel: { show: true, color: "rgba(139,147,167,0.75)", fontSize: 7,
                 showMinLabel: false, formatter: v => fmtCorto(v) }
  });

  chartSeries.push({
    name: c, type: "line", xAxisIndex: i, yAxisIndex: i,
    smooth: pocosPuntos ? 0.15 : 0.32,
    symbol: "none",
    lineStyle: { width: 1.4, color: col_ }, itemStyle: { color: col_ },
    areaStyle: { opacity: 0.35, color: { type: "linear", x: 0, y: 0, x2: 0, y2: 1,
      colorStops: [{ offset: 0, color: col_ }, { offset: 1, color: "rgba(10,14,23,0.03)" }] } },
    endLabel: { show: true, distance: 3, fontSize: 8, color: col_,
                formatter: p => fmtCorto(p.value[1]) },
    data: buckets.map(t => [t, num(matrix[t] ? matrix[t][c] : 0)])
  });

  const taaCat = 100.0 * catAprob[c] / Math.max(catTotals[c], 1);
  const maxCat = buckets.reduce((m, t) => Math.max(m, num(matrix[t] ? matrix[t][c] : 0)), 0);
  titles.push({
    text: c.length > 18 ? c.slice(0, 17) + "…" : c,
    subtext: `${fmtCorto(catTotals[c])} tx · TAA ${fmtPct(taaCat)} · pico ${fmtCorto(maxCat)}/${bkMin}min (${porMin(maxCat)}/min)`,
    left: left + "%", top: (top - 7.5) + "%",
    textStyle: { color: col_, fontSize: 9.5, fontWeight: 700 },
    subtextStyle: { color: textSec, fontSize: 8 },
    itemGap: 1
  });
});

// ---------- HEADER ----------
const graphics = [
  { type:"text", left:12, top:8, style:{ text:"Modalidades · evolución", fill:aqua, font:"bold 13px sans-serif" }, silent:true },
  { type:"text", left:12, top:25, style:{ text:`${rangoTxt} · cada punto = TOTAL de ${bkMin} min · una faceta por modalidad, escala propia`, fill:textSec, font:"10px sans-serif" }, silent:true },
  { type:"text", right:16, top:8, style:{ text:filtroTxt, fill:cliente.color, font:"10px sans-serif", textAlign:"right" }, silent:true }
];

// ---------- TOOLTIP ----------
// Muestra la modalidad sobre la que se esta parado y ademas las otras en el mismo
// instante: con escalas propias no se pueden comparar a ojo, asi que la comparacion
// tiene que darla el tooltip.
function tooltipFormatter(params) {
  if (!params || !params.length) return "";
  const p = params[0];
  const t = p.value[0];
  const cHover = p.seriesName;
  const dh = (detail[t] || {})[cHover] || {};
  const totH = num(matrix[t] ? matrix[t][cHover] : 0);

  const otras = catsFacetas
    .filter(c => c !== cHover && detail[t] && detail[t][c])
    .map(c => {
      const dd = detail[t][c];
      return `<div style="margin-top:2px;color:${textSec}">
        <span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:${colorDe(c, cats.indexOf(c))};margin-right:6px"></span>
        ${esc(c)}: ${fmtNum(num(matrix[t] ? matrix[t][c] : 0))} tx (${porMin(num(matrix[t] ? matrix[t][c] : 0))}/min) · TAA ${fmtPct(dd.tasa)}
      </div>`;
    }).join("");

  return `
    <div style="min-width:270px;max-width:420px">
      <div style="font-weight:800;color:${text};margin-bottom:4px">${fmtHora(t)} – ${finBucket(t)}<span style="font-weight:400;color:${textSec}"> · ventana de ${bkMin} min</span></div>
      <div style="color:${textSec};font-size:11px;margin-bottom:5px">${esc(filtroTxt)}</div>
      <div>
        <span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:${colorDe(cHover, cats.indexOf(cHover))};margin-right:6px"></span>
        <b>${esc(cHover)}</b>: ${fmtNum(totH)} tx en ${bkMin} min <b style="color:${text}">(${porMin(totH)}/min)</b> ·
        <span style="color:${aqua}">${fmtNum(num(dh.a))} ✓</span> ·
        <span style="color:#EF6A85">${fmtNum(num(dh.d))} ✗</span> ·
        TAA <b>${fmtPct(num(dh.tasa))}</b>
      </div>
      ${otras}
    </div>`;
}

// ---------- RENDER ----------
return {
  backgroundColor: bg,
  graphic: graphics,
  title: titles,
  tooltip: {
    trigger: "axis", appendToBody: false, confine: true, enterable: false,
    backgroundColor: "rgba(11,15,24,0.78)", borderColor: "rgba(0,244,196,0.55)",
    borderWidth: 1, padding: 9,
    textStyle: { color: text, fontSize: 11, fontFamily: "Inter, Roboto, sans-serif" },
    formatter: tooltipFormatter
  },
  axisPointer: { link: [{ xAxisIndex: "all" }], lineStyle: { color: "rgba(255,255,255,0.22)" } },
  grid: grids, xAxis: xAxes, yAxis: yAxes, series: chartSeries,
  animation: false
};

options.getOption:
