  if (Math.abs(x) >= 1e6) return (x / 1e6).toLocaleString("es-AR", { maximumFractionDigits: 1 }) + " M";
  if (Math.abs(x) >= 1e3) return (x / 1e3).toLocaleString("es-AR", { maximumFractionDigits: 0 }) + " k";
