  colorStops: [{ offset: 0, color: c1 }, { offset: 1, color: c2 }]
});

const rangoTxt = `${fmtFechaHora(fieldAny(["rango_desde"])[0])} – ${fmtFechaHora(fieldAny(["rango_hasta"])[0])}`;

if (!cats.length || totales.every(v => v === 0)) return sinDatos();

const totalGeneral = totales.reduce((a, b) => a + b, 0);
const taaGeneral = 100.0 * aprob.reduce((a, b) => a + b, 0) / Math.max(totalGeneral, 1);
const colorTasa = t => t >= 95 ? green : t >= 85 ? amber : coral;
const share = i => 100.0 * totales[i] / Math.max(totalGeneral, 1);

// ---------- HEADER ----------
const graphics = [
  { type:"text", left:12, top:8, style:{ text:"Plataformas de Pago", fill:aqua, font:"bold 13px sans-serif" }, silent:true },
  { type:"text", left:12, top:25, style:{ text:`${rangoTxt} · rango del selector`, fill:textSec, font:"10px sans-serif" }, silent:true },
  { type:"text", right:16, top:8, style:{ text:filtroTxt, fill:cliente.color, font:"10px sans-serif", textAlign:"right" }, silent:true },
  { type:"text", right:16, top:25, style:{ text:`${fmtNum(totalGeneral)} tx · TAA `, fill:textSec, font:"10px sans-serif", textAlign:"right" }, silent:true }
];
// TAA global con color semáforo, pegada al texto anterior
graphics[3].style.text = `${fmtNum(totalGeneral)} tx  ·  TAA ${fmtPct(taaGeneral)}`;
graphics[3].style.fill = colorTasa(taaGeneral);

// ---------- TOOLTIP ----------
function tooltipFormatter(params) {
  const i = params[0].dataIndex;
  return `
    <div style="min-width:230px">
      <div style="font-weight:800;color:${text};margin-bottom:5px">${esc(cats[i])}
        <span style="color:${textSec};font-weight:400;font-size:10px">· ${fmtPct(share(i))} del total</span></div>
      <div style="color:${textSec};font-size:11px;margin-bottom:7px">${esc(filtroTxt)}</div>
      <div style="color:${text};font-size:11px">
        Transacciones: <b>${fmtNum(totales[i])}</b><br/>
        Aprobadas: <b style="color:${aqua}">${fmtNum(aprob[i])}</b><br/>
        Denegadas: <b style="color:#EF6A85">${fmtNum(deneg[i])}</b><br/>
        Tasa de aceptación: <b style="color:${colorTasa(tasas[i])}">${fmtPct(tasas[i])}</b>
      </div>
    </div>`;
}

// ---------- RENDER ----------
return {
  backgroundColor: bg,

  title: {
    text: "Transacciones, aprobadas, denegadas y TAA por gateway (top 12)",
    left: 12, top: 43,
    textStyle: { color: text, fontSize: 12, fontWeight: 800 }
  },

  legend: {
    top: 65, left: 12, itemWidth: 7, itemHeight: 7, icon: "circle", itemGap: 9,
    textStyle: { color: textSec, fontSize: 8.5 },
    inactiveColor: "rgba(139,147,167,0.35)",
    data: ["Aprobadas", "Denegadas", "Tasa de aceptación (%)"]
  },

  tooltip: {
    trigger: "axis", appendToBody: false, confine: true, enterable: false,
    backgroundColor: "rgba(11,15,24,0.78)", borderColor: "rgba(0,244,196,0.55)", borderWidth: 1, padding: 9,
    textStyle: { color: text, fontSize: 11, fontFamily: "Inter, Roboto, sans-serif" },
    axisPointer: { type: "shadow", shadowStyle: { color: "rgba(255,255,255,0.06)" } },
    formatter: tooltipFormatter
  },

  // bottom 26 recortaba las etiquetas rotadas ('...tico IBM'). Con rotacion hacen
  // falta ~58 px para que entre un nombre largo a 28 grados.
  grid: { left: 52, right: 46, top: 96, bottom: cats.length > 6 ? 68 : 26 },

  xAxis: {
    type: "category", data: cats,
    axisLine: { lineStyle: { color: "rgba(148,163,184,0.16)" } },
    axisTick: { show: false },
    axisLabel: {
      color: textSec, fontSize: 8.5, interval: 0, rotate: cats.length > 6 ? 28 : 0,
      // se acorta a 16 caracteres: el nombre completo esta en el tooltip
      formatter: (name, i) => cats.length > 6
        ? (String(name).length > 24 ? String(name).slice(0, 23) + "\u2026" : name)
        : `${name}\n${fmtPct(share(i))}`
    }
  },

  yAxis: [
    {
      type: "value", minInterval: 1,
      axisLine: { show: false }, axisTick: { show: false },
      axisLabel: { color: textSec, fontSize: 8.5, formatter: v => fmtCorto(v) },
      splitLine: { lineStyle: { color: grid } }
    },
    {
      type: "value", min: 0, max: 100,
      axisLine: { show: false }, axisTick: { show: false },
      axisLabel: { color: textSec, fontSize: 8.5, formatter: "{value}%" },
      splitLine: { show: false }
    }
  ],

  series: [
    {
      name: "Aprobadas", type: "bar", stack: "tx", yAxisIndex: 0, barMaxWidth: 40,
      data: aprob,
      itemStyle: { color: grad("rgba(0,244,196,0.95)", "rgba(0,244,196,0.45)") },
      emphasis: { itemStyle: { color: aqua } }
    },
    {
      name: "Denegadas", type: "bar", stack: "tx", yAxisIndex: 0, barMaxWidth: 40,
      data: deneg,
      itemStyle: { color: grad("rgba(207,67,96,0.95)", "rgba(169,52,77,0.55)"), borderRadius: [3, 3, 0, 0] },
      emphasis: { itemStyle: { color: "#EF6A85" } },
      label: {
        show: true, position: "top", color: textSoft, fontSize: 8.5,
        formatter: p => fmtCorto(totales[p.dataIndex])
      }
    },
    {
      name: "Tasa de aceptación (%)", type: "line", yAxisIndex: 1,
      symbol: "circle", symbolSize: 9,
      lineStyle: { width: 1.5, color: amber },
      itemStyle: { color: amber, borderColor: "rgba(231,180,50,0.35)", borderWidth: 4 },
      data: tasas.map(t => ({ value: t, itemStyle: { color: colorTasa(t), borderColor: colorTasa(t)+"55", borderWidth: 4 } })),
      label: { show: true, position: "top", color: amber, fontSize: 8.5, formatter: p => fmtPct(p.value) },
      z: 5
    }
  ],

  graphic: graphics,
  animation: false
};

