// ======================================================================================
// BUSINESS CHART — PLATAFORMAS DE PAGO · FACETAS (small multiples)
// Una mini-serie por gateway: compara formas y detecta caídas individuales
// que el apilado esconde. Ordenadas por volumen desc.
// ======================================================================================

const aqua = "#00F4C4";
const amber = "#E7B432";
const violet = "#7C6AE6";
const coral = "#CF4360";
const slate = "#64748B";
const gray = "#94A3B8";
const blue = "#3B82F6";
const green = "#22C55E";
const naranja = "#FF8A5C";

const bg = "#0a0e17";
const text = "#E5E7EB";
const textSec = "#8b93a7";
const textSoft = "#CBD5E1";

const PALETA = [aqua, blue, amber, violet, naranja, green, "#5EEAD4", "#93C5FD", gray, slate];

// ---------- helpers ----------
const series0 = context.panel?.data?.series || [];
const s = series0[0];
function valuesOfField(f){ if(!f) return []; return typeof f.values?.toArray==="function" ? f.values.toArray() : Array.from(f.values||[]); }
function fieldAny(names){
  if(!s||!s.fields) return [];
  for(const n of names){ const f=s.fields.find(x=>String(x.name).toLowerCase()===String(n).toLowerCase()); const v=valuesOfField(f); if(v.length) return v; }
  return [];
}
const num=(v,d=0)=>{const x=Number(v);return Number.isFinite(x)?x:d;};
const fmtNum=v=>num(v).toLocaleString("es-AR");
const fmtPct=v=>`${num(v).toFixed(1)}%`;
const esc=v=>String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
const fmtCorto=v=>{const x=num(v);if(Math.abs(x)>=1e6)return (x/1e6).toLocaleString("es-AR",{maximumFractionDigits:1})+" M";if(Math.abs(x)>=1e3)return (x/1e3).toLocaleString("es-AR",{maximumFractionDigits:0})+" k";return fmtNum(x);};
function fmtHora(v){const d=new Date(v);return isNaN(d.getTime())?String(v):d.toLocaleTimeString("es-AR",{hour:"2-digit",minute:"2-digit",hour12:false});}
function fmtFechaHora(v){const d=new Date(v);return isNaN(d.getTime())?String(v):d.toLocaleString("es-AR",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit",hour12:false});}

// ---------- filtros (header) ----------
function rv(str){ try{ if(context?.grafana?.replaceVariables) return context.grafana.replaceVariables(str);}catch(e){} return str; }
function cleanValue(v){ const x=String(v??"").trim(); if(!x||x==="-1")return null; const u=x.toUpperCase(); if(u==="ALL"||u==="TODAS LAS MARCAS"||u==="$__ALL"||x.startsWith("${"))return null; return x; }
const selCuit=cleanValue(rv("${cuit:raw}"));
const filtroTxt=[selCuit?`CUIT ${selCuit}`:"PAYWAY GENERAL",
  cleanValue(rv("${establecimiento:raw}"))?`Est. ${cleanValue(rv("${establecimiento:raw}"))}`:"Todos los est.",
  cleanValue(rv("${marca:raw}"))||"Todas las marcas"].join(" · ");

// ---------- empty ----------
function sinDatos(){
  return { backgroundColor:bg, graphic:[
    {type:"text",left:12,top:8,style:{text:"Plataformas de Pago · facetas",fill:aqua,font:"800 12px sans-serif"},silent:true},
    {type:"text",left:"center",top:"middle",style:{text:"Sin transaccionamiento",fill:textSec,font:"800 12px sans-serif",textAlign:"center"},silent:true}
  ], xAxis:{show:false},yAxis:{show:false},series:[],animation:false };
}
if(!s||!s.fields||s.fields.length===0) return sinDatos();

// ---------- pivot ----------
const tiemposRaw=fieldAny(["time","bk"]);
const catsRaw=fieldAny(["categoria"]);
const totRaw=fieldAny(["total_tx"]);
const aprRaw=fieldAny(["aprobadas"]);
const tasaRaw=fieldAny(["tasa_aprobacion"]);
if(!tiemposRaw.length||!catsRaw.length) return sinDatos();

const rangoTxt=`${fmtFechaHora(fieldAny(["rango_desde"])[0])} – ${fmtFechaHora(fieldAny(["rango_hasta"])[0])}`;

const porCat={}, detalle={};
for(let i=0;i<tiemposRaw.length;i++){
  const t=new Date(tiemposRaw[i]).getTime();
  if(!Number.isFinite(t)) continue;
  const c=String(catsRaw[i]);
  (porCat[c]=porCat[c]||[]).push([t,num(totRaw[i])]);
  (detalle[c]=detalle[c]||{})[t]={a:num(aprRaw[i]),tasa:num(tasaRaw[i]),tot:num(totRaw[i])};
}
const catTotals={}, catAprob={};
for(const c in porCat){ catTotals[c]=porCat[c].reduce((x,p)=>x+p[1],0); catAprob[c]=Object.values(detalle[c]).reduce((x,d)=>x+d.a,0); }
const cats=Object.keys(porCat).sort((a,b)=>{
  if(a==="NO MAPEADO") return 1; if(b==="NO MAPEADO") return -1;
  if(a==="Otras plataformas") return 1; if(b==="Otras plataformas") return -1;
  return catTotals[b]-catTotals[a];
});
for(const c in porCat) porCat[c].sort((x,y)=>x[0]-y[0]);
if(!cats.length||cats.every(c=>catTotals[c]===0)) return sinDatos();

// ---------- LA UNIDAD ----------
// Cada punto es el TOTAL del bucket. El 151 no lo calculaba: se deduce de la
// separacion entre los dos primeros instantes de la serie mas larga.
const _ts = Object.values(porCat).reduce((a,b)=>a.length>=b.length?a:b, []);
const bkMin = _ts.length >= 2 ? Math.max(1, Math.round((_ts[1][0] - _ts[0][0]) / 60000)) : 15;
const porMin = v => fmtNum(Math.round(num(v) / Math.max(bkMin, 1)));
const finBucket = t => fmtHora(t + Math.max(bkMin, 1) * 60000);

const colorDe=(c,i)=> c==="NO MAPEADO"?coral : c==="Otras plataformas"?slate : PALETA[i%PALETA.length];

// ---------- layout de facetas ----------
const n=cats.length;
const COLS=Math.min(5,n), ROWS=Math.ceil(n/COLS);
// TOP: el titulo y el subtitulo ocupan ~11%, y cada faceta necesita 7.5% arriba
// para su propio titulo. Con 36 sobraba espacio muerto arriba y la fila de abajo
// quedaba con 1,5% de aire: su titulo se pegaba al grafico de la fila de arriba.
const TOP=19, BOT=3, GAPX=3.4, GAPY=13;
const usableW=100-4-4-(COLS-1)*GAPX;
const cellW=usableW/COLS;
const usableH=100-TOP-BOT-(ROWS-1)*GAPY;
const cellH=usableH/ROWS;

const grids=[], xAxes=[], yAxes=[], seriesArr=[], titles=[];
cats.forEach((c,i)=>{
  const col=i%COLS, fila=Math.floor(i/COLS);
  const left=4+col*(cellW+GAPX);
  const top=TOP+fila*(cellH+GAPY);
  grids.push({ left:left+"%", top:top+"%", width:cellW+"%", height:cellH+"%" });
  xAxes.push({ gridIndex:i, type:"time",
    axisLine:{lineStyle:{color:"rgba(148,163,184,0.14)"}}, axisTick:{show:false}, splitLine:{show:false},
    axisLabel: fila===ROWS-1 ? {color:textSec,fontSize:7.5,hideOverlap:true,formatter:v=>fmtHora(v)} : {show:false} });
  yAxes.push({ gridIndex:i, type:"value", min:0, splitNumber:2,
    axisLine:{show:false}, axisTick:{show:false},
    splitLine:{show:true,lineStyle:{color:"rgba(148,163,184,0.10)"}},
    axisLabel:{show:true,color:"rgba(139,147,167,0.75)",fontSize:7,showMinLabel:false,formatter:v=>fmtCorto(v)} });
  const col_=colorDe(c,i);
  seriesArr.push({
    name:c, type:"line", xAxisIndex:i, yAxisIndex:i,
    smooth:0.35, symbol:"none",
    lineStyle:{width:1.4,color:col_}, itemStyle:{color:col_},
    areaStyle:{opacity:0.35,color:{type:"linear",x:0,y:0,x2:0,y2:1,
      colorStops:[{offset:0,color:col_},{offset:1,color:"rgba(10,14,23,0.03)"}]}},
    endLabel:{show:true,distance:3,fontSize:8,color:col_,formatter:p=>fmtCorto(p.value[1])},
    data:porCat[c]
  });
  const taaCat=100.0*catAprob[c]/Math.max(catTotals[c],1);
  const maxCat=porCat[c].reduce((m,p)=>Math.max(m,p[1]),0);
  titles.push({
    text:c.length>18?c.slice(0,17)+"…":c,
    subtext:`${fmtCorto(catTotals[c])} tx · TAA ${fmtPct(taaCat)} · pico ${fmtCorto(maxCat)}/${bkMin}min (${porMin(maxCat)}/min)`,
    left:left+"%", top:(top-7.5)+"%",
    textStyle:{color: c==="NO MAPEADO"?coral:textSoft, fontSize:9.5, fontWeight:700},
    subtextStyle:{color:textSec,fontSize:8},
    itemGap:1
  });
});

// ---------- render ----------
return {
  backgroundColor:bg,
  graphic:[
    {type:"text",left:12,top:8,style:{text:"Plataformas de Pago · 15m",fill:aqua,font:"bold 13px sans-serif"},silent:true},
    {type:"text",left:12,top:25,style:{text:`${rangoTxt} · cada punto = TOTAL de ${bkMin} min · escala propia por gateway`,fill:textSec,font:"10px sans-serif"},silent:true},
    {type:"text",right:16,top:8,style:{text:filtroTxt,fill:textSoft,font:"10px sans-serif",textAlign:"right"},silent:true}
  ],
  title:titles,
  tooltip:{
    trigger:"axis", appendToBody:false, confine:true,
    backgroundColor:"rgba(11,15,24,0.82)", borderColor:"rgba(0,244,196,0.55)", borderWidth:1, padding:8,
    textStyle:{color:text,fontSize:11},
    formatter:params=>{
      if(!params||!params.length) return "";
      const p=params[0]; const t=p.value[0]; const c=p.seriesName;
      const d=(detalle[c]||{})[t]||{};
      return `<b>${esc(c)}</b> · ${fmtHora(t)} – ${finBucket(t)} <span style="color:${textSec}">(ventana de ${bkMin} min)</span><br/>` +
             `Transacciones: <b>${fmtNum(d.tot||p.value[1])}</b> en ${bkMin} min <b>(${porMin(d.tot||p.value[1])}/min)</b><br/>` +
             `Aprobadas: <b style="color:${aqua}">${fmtNum(d.a||0)}</b> · TAA <b>${fmtPct(d.tasa||0)}</b>`;
    }
  },
  axisPointer:{ link:[{xAxisIndex:"all"}], lineStyle:{color:"rgba(255,255,255,0.25)"} },
  grid:grids, xAxis:xAxes, yAxis:yAxes, series:seriesArr,
  animation:false
};
